import type { TarotCard } from '../types';

export const TAROT_DECK: TarotCard[] = [
  // ─── Major Arcana (0-21) ───
  { id: 0, name: '愚者', nameEn: 'The Fool', suit: 'major', meaning: '愚者代表人生新篇章的启程。你正站在悬崖边缘，虽然脚下是未知的深渊，但心中却充满纯真的信任与无畏的勇气。这张牌呼唤你放下过往的包袱与恐惧，像初生的旅人一般迈出第一步。冒险的旅程本身即是奖赏，每一次跌倒都是灵魂成长的养分。相信宇宙的安排，拥抱未知，因为你所追寻的答案，往往藏在最意想不到的转角。', meaningEn: 'The Fool represents a new chapter in life. You stand at the edge of a cliff, facing the unknown with innocent trust and fearless courage. This card calls you to let go of past baggage and fears, and take the first step like a newborn traveler. The journey itself is the reward—every fall nourishes the soul\'s growth. Trust the universe and embrace the unknown, for the answers you seek often hide around the most unexpected corners.', meaningReversed: '逆位的愚者警示着鲁莽与缺乏准备的行动。你可能被一时的冲动蒙蔽，忽视了脚下的危险信号。这不是鼓励畏缩不前，而是提醒你：真正的勇气来自于清醒的认知，而非盲目的乐观。在做出重大决定之前，请先审视自己是否忽略了关键细节。成熟不是停止冒险，而是学会带着智慧去冒险。', meaningReversedEn: 'The reversed Fool warns against reckless and unprepared action. You may be blinded by impulse, ignoring danger signals beneath your feet. True courage comes from clear awareness, not blind optimism. Before making major decisions, examine whether you have overlooked critical details. Maturity is not about stopping adventure, but learning to adventure with wisdom.', isReversed: false },
  { id: 1, name: '魔术师', nameEn: 'The Magician', suit: 'major', meaning: '魔术师象征着显化与创造力的巅峰时刻。你手中握有火、水、风、土四元素的资源，宇宙的能量正汇聚于你的指尖，等待被你塑造成具体的现实。这是将梦想落地为成果的绝佳时机，你的意志力足以撼动山岳。相信自己拥有改变现状的能力，因为你就是连接天与地的通道。主动出击，世界将回应你的召唤。', meaningEn: 'The Magician symbolizes the peak of manifestation and creativity. You hold the resources of all four elements—fire, water, air, and earth. The universe\'s energy converges at your fingertips, waiting to be shaped into tangible reality. This is the perfect time to ground your dreams into results. Believe in your ability to change your circumstances, for you are the channel connecting heaven and earth. Take the initiative, and the world will answer your call.', meaningReversed: '逆位的魔术师揭示了能量的错配与资源的浪费。你可能拥有才华与工具，却因为缺乏专注或自信而无法有效运用。要警惕自我欺骗的陷阱——你是否在用忙碌来掩饰方向的迷失？重新审视你的目标，清理那些消耗你精力的杂务。真正的力量不在于你拥有多少，而在于你能否将所拥有的聚焦于一点，穿透现实。', meaningReversedEn: 'The reversed Magician reveals misaligned energy and wasted resources. You may possess talent and tools but lack the focus or confidence to use them effectively. Beware the trap of self-deception—are you using busyness to mask a lack of direction? Re-examine your goals and clear away distractions. True power lies not in how much you have, but in your ability to focus what you have to pierce through reality.', isReversed: false },
  { id: 2, name: '女祭司', nameEn: 'The High Priestess', suit: 'major', meaning: '女祭司守护着潜意识与直觉的神秘殿堂。在喧嚣的世界中，她邀请你退回内心深处的寂静圣地，那里藏着你早已知道却尚未承认的答案。这不是依赖逻辑分析的时刻，而是信任第六感、梦境与微妙征兆的时刻。你内在的智慧比任何外部权威都更为古老和真实。静心冥想，让直觉如月光般照亮你前行的幽径。', meaningEn: 'The High Priestess guards the mysterious temple of the subconscious and intuition. In a noisy world, she invites you to retreat into the silent sanctuary within, where answers you already know but have not yet acknowledged await. This is not a time for logical analysis, but for trusting your sixth sense, dreams, and subtle signs. Your inner wisdom is more ancient and true than any external authority. Meditate in stillness and let intuition illuminate your path like moonlight.', meaningReversed: '逆位的女祭司暗示着直觉的阻塞与内在声音的淹没。你可能过度依赖外界的噪音——他人的意见、社会的标准、即时的信息——而忽略了自己灵魂深处的低语。秘密可能被隐藏，真相被迷雾笼罩。此刻你需要刻意创造独处的时间，切断外在的干扰，重新与自己建立连接。答案不在他处，它一直安静地等在你心里。', meaningReversedEn: 'The reversed High Priestess suggests blocked intuition and a drowned inner voice. You may rely too heavily on external noise—others\' opinions, societal standards, instant information—while ignoring your soul\'s quiet whisper. Secrets may be hidden, and truth obscured by fog. Create intentional solitude, cut external interference, and reconnect with yourself. The answer is not elsewhere; it has been waiting quietly within you.', isReversed: false },
  { id: 3, name: '皇后', nameEn: 'The Empress', suit: 'major', meaning: '皇后是丰饶、滋养与创造力的化身。她坐在金色的麦田中，脚下是流淌的生命之河，提醒你去拥抱感官世界的美好与丰盛。无论是孕育一个新项目、一段关系，还是滋养自己的身心，这都是生命力蓬勃绽放的时刻。像大地母亲一样慷慨地给予，也像她一样欣然地接受宇宙的馈赠。享受此刻的繁花似锦，因为你值得拥有这一切。', meaningEn: 'The Empress is the embodiment of abundance, nurturing, and creativity. She sits in golden wheat fields with the river of life flowing at her feet, reminding you to embrace the beauty and abundance of the sensory world. Whether birthing a new project, a relationship, or nurturing yourself, this is a time of vibrant life force. Give generously like Mother Earth, and accept the universe\'s gifts with equal grace. Enjoy this flourishing moment, for you deserve it all.', meaningReversed: '逆位的皇后指向创造力的枯竭与自我滋养的匮乏。你可能感到身心俱疲，像是在给予他人沃土的同时，却让自己的心田变得贫瘠。过度依赖他人的认可，或是对物质安全的焦虑，都可能阻塞你与生俱来的丰盛之流。是时候重新将目光转向自己：什么能真正让你感到愉悦？允许自己休息、享受、毫无愧疚地宠爱自己，丰饶会随之回流。', meaningReversedEn: 'The reversed Empress points to creative depletion and lack of self-nourishment. You may feel physically and mentally exhausted, giving fertile ground to others while your own field becomes barren. Over-reliance on external validation or anxiety about material security may block your natural abundance. Turn your gaze inward: what truly brings you joy? Allow yourself to rest, enjoy, and indulge without guilt—abundance will flow back to you.', isReversed: false },
  { id: 4, name: '皇帝', nameEn: 'The Emperor', suit: 'major', meaning: '皇帝代表着秩序、权威与稳固的结构。他是疆域的守护者，以铁律与智慧建立起让万物得以生长的框架。这张牌出现在你的生命中，意味着你需要以坚定的决心和清晰的边界来掌控局面。无论是事业、家庭还是个人目标，此刻都需要规则、计划与执行力。展现你的领导力，站稳脚跟，因为世界需要一个能够承担责任的你。', meaningEn: 'The Emperor represents order, authority, and solid structure. He is the guardian of the realm, establishing frameworks with iron discipline and wisdom that allow all things to grow. This card appears when you need to take charge with firm determination and clear boundaries. Whether in career, family, or personal goals, rules, plans, and execution are needed now. Show your leadership, stand your ground—the world needs someone who can take responsibility.', meaningReversed: '逆位的皇帝警示着控制的失衡。你可能陷入了过度僵化、独裁或专横的境地，用铁拳压制了生命的流动性；也可能恰恰相反，你在该站出来的时候退缩了，让混乱取代了秩序。问问自己：你是在建立保护性的结构，还是在建造囚禁自己的牢笼？真正的力量来自于灵活与坚定并存——懂得何时坚持，何时放手。', meaningReversedEn: 'The reversed Emperor warns of imbalanced control. You may have fallen into excessive rigidity, authoritarianism, or tyranny, suppressing life\'s flow with an iron fist; or conversely, you may be retreating when you should stand up, letting chaos replace order. Ask yourself: are you building protective structures, or prisons that confine yourself? True strength lies in the balance of flexibility and firmness—knowing when to hold on and when to let go.', isReversed: false },
  { id: 5, name: '教皇', nameEn: 'The Hierophant', suit: 'major', meaning: '教皇是 tradition、信仰与精神导师的象征。他站在神圣与世俗的交界处，手中握着开启智慧之门的钥匙。这张牌暗示你正在寻求更高层次的指引，或是需要回归那些经得起时间考验的价值观与知识体系。一位导师、一本经典、或一个古老的传统，都可能为你提供此刻最需要的答案。尊重既定的道路，因为在传统中隐藏着世代积累的智慧。', meaningEn: 'The Hierophant symbolizes tradition, faith, and spiritual guidance. He stands at the intersection of the sacred and the mundane, holding the key to wisdom\'s door. This card suggests you are seeking higher guidance, or need to return to time-tested values and knowledge systems. A mentor, a classic text, or an ancient tradition may provide the answers you need most right now. Respect the established path, for within tradition lies wisdom accumulated across generations.', meaningReversed: '逆位的教皇呼唤着对固有教条的质疑与反叛。你可能感到被传统、组织或他人的期待所束缚，内心的声音在呐喊着要走一条属于自己的路。这不是对智慧的否定，而是对盲目服从的拒绝。勇于打破陈规，建立属于你自己的精神信仰与价值体系。有时候，灵魂的成长必须发生在正统的框架之外。', meaningReversedEn: 'The reversed Hierophant calls for questioning established dogma and rebellion. You may feel bound by tradition, institutions, or others\' expectations, with your inner voice crying out to forge your own path. This is not a rejection of wisdom, but a refusal of blind obedience. Dare to break conventions and establish your own spiritual beliefs and value system. Sometimes, the soul must grow outside orthodox frameworks.', isReversed: false },
  { id: 6, name: '恋人', nameEn: 'The Lovers', suit: 'major', meaning: '恋人牌不仅仅是爱情的象征，更是关于选择与和谐的深层寓言。它代表着两颗灵魂在真诚与信任中的相遇，也代表着你内在阳性力量与阴性能量的完美合一。一个重大的抉择正摆在你面前，而这个选择必须基于你内心最真实的价值观。真诚的关系、道德的抉择、以及对自己本性的忠实，将为你带来生命中最珍贵的礼物。', meaningEn: 'The Lovers is not merely a symbol of romance, but a deeper allegory of choice and harmony. It represents the meeting of two souls in sincerity and trust, and the perfect union of your inner masculine and feminine energies. A significant choice lies before you, and this decision must be based on your truest values. Sincere relationships, moral choices, and fidelity to your own nature will bring life\'s most precious gifts.', meaningReversed: '逆位的恋人揭示了关系中的不和谐与价值观的冲突。你可能正面临一个艰难的选择，而恐惧或外界的诱惑让你偏离了内心的真实。在人际关系中，信任的裂痕、沟通的障碍、或是秘密的背叛都可能浮出水面。这张牌提醒你：表面的和谐若建立在虚假之上，终将崩塌。勇敢地面对真相，即使它意味着痛苦的分离。', meaningReversedEn: 'The reversed Lovers reveals disharmony in relationships and conflicting values. You may face a difficult choice where fear or external temptation leads you away from your inner truth. In relationships, cracks in trust, communication barriers, or secret betrayals may surface. This card reminds you: surface harmony built on falsehood will eventually collapse. Face the truth bravely, even if it means painful separation.', isReversed: false },
  { id: 7, name: '战车', nameEn: 'The Chariot', suit: 'major', meaning: '战车是意志力、胜利与不懈前进的图腾。驭手驾驭着两头象征对立力量的狮身人面兽，不是通过暴力，而是通过坚定的意念让它们共同前进。这张牌宣告着你正处于一个需要全力以赴的关键时刻。设定你的目标，排除万难，不要让任何障碍阻挡你前进的步伐。成功属于那些敢于掌控自己命运的人，而你已经具备了赢得这场战役的所有条件。', meaningEn: 'The Chariot is the totem of willpower, victory, and relentless forward movement. The charioteer guides two sphinxes symbolizing opposing forces, not through violence but through unwavering determination. This card declares that you are at a critical moment requiring full commitment. Set your goals, overcome all obstacles, and let nothing stand in your way. Success belongs to those who dare to control their own destiny, and you already possess all conditions to win this battle.', meaningReversed: '逆位的战车暗示着力量的失控与方向的迷失。你可能像一辆脱缰的战车，被两匹互相拉扯的马拖向混乱，或是在过度的自信中横冲直撞。挫败感可能让你怀疑自己的能力，而愤怒与急躁只会让你离目标更远。停下来，重新握紧缰绳。问问自己：你究竟为何而战？只有明确了真正的方向，力量才能化为胜利的推进。', meaningReversedEn: 'The reversed Chariot suggests失控的力量 and lost direction. You may be like a runaway chariot, dragged toward chaos by two pulling horses, or charging recklessly in overconfidence. Frustration may make you doubt your abilities, while anger and impatience only push you further from your goal. Stop and re-grasp the reins. Ask yourself: what are you truly fighting for? Only with clear direction can strength become victorious propulsion.', isReversed: false },
  { id: 8, name: '力量', nameEn: 'Strength', suit: 'major', meaning: '力量牌展现的不是外在的强悍，而是内在的柔韧与勇气。画面中女子温柔地合上狮子的嘴，象征着以爱与耐心驯服本能与恐惧。你拥有面对任何挑战的内在力量，这种力量不来自于压迫，而来自于接纳与理解。无论当前的困境看起来多么凶猛，保持内心的平静与慈悲，你将发现自己比想象中更强大。温柔，是最坚韧的力量。', meaningEn: 'Strength shows not external might, but inner resilience and courage. The woman gently closes the lion\'s mouth, symbolizing taming instinct and fear with love and patience. You possess the inner strength to face any challenge—this power comes not from oppression, but from acceptance and understanding. No matter how fierce the current困境 appears, maintain inner peace and compassion, and you will discover you are stronger than imagined. Gentleness is the most resilient strength.', meaningReversed: '逆位的力量指向内在勇气的匮乏与情绪管理的失衡。你可能感到被自己的恐惧、愤怒或欲望所控制，而非驾驭它们。自我怀疑像阴影一样笼罩着你，让你在面对挑战时退缩或爆发。但请记住，狮子并非要被消灭，而是要被理解。承认自己的脆弱并不可耻，真正的力量始于对自己所有面向的温柔接纳。', meaningReversedEn: 'The reversed Strength points to lack of inner courage and emotional imbalance. You may feel controlled by your own fears, anger, or desires rather than mastering them. Self-doubt casts shadows over you, making you retreat or explode when facing challenges. But remember: the lion need not be destroyed, only understood. Acknowledging vulnerability is not shameful—true strength begins with gentle acceptance of all aspects of yourself.', isReversed: false },
  { id: 9, name: '隐士', nameEn: 'The Hermit', suit: 'major', meaning: '隐士提着灯笼，独自站在雪山之巅。这不是孤独的放逐，而是主动选择的内省与追寻。当外界的喧嚣无法给你答案时，这张牌邀请你退入内心深处的寂静。在独处的时光中，你将找到那盏照亮真理的明灯。智慧往往诞生于静默之中，而此刻的你，正需要远离人群，与自己的灵魂对话。内在的指引，远比外界的声音更为清晰。', meaningEn: 'The Hermit carries his lantern, standing alone on the snowy mountain peak. This is not lonely exile, but chosen introspection and pursuit. When external noise cannot give you answers, this card invites you to retreat into inner silence. In solitude, you will find the lantern that illuminates truth. Wisdom is often born in stillness, and you now need to distance yourself from the crowd to dialogue with your own soul. Inner guidance is far clearer than external voices.', meaningReversed: '逆位的隐士警示着两种极端：一是过度的退缩与孤立，你可能在逃避而非面对，将孤独变成了自我囚禁的牢笼；二是在不该独处的时候强行封闭自己，错过了外界伸来的援手与重要的连接。 introspection 是必要的，但过度的 introspection 会变成 paralysis。适度地走出你的洞穴，让光芒不仅照亮内心，也温暖你与世界的连接。', meaningReversedEn: 'The reversed Hermit warns of two extremes: excessive withdrawal and isolation, where you escape rather than face reality, turning solitude into a self-imprisoning cage; or forcing solitude when you should not, missing out on helping hands and important connections. Introspection is necessary, but excessive introspection becomes paralysis. Moderately step out of your cave—let light illuminate not only your inner world but also warm your connection with the world.', isReversed: false },
  { id: 10, name: '命运之轮', nameEn: 'Wheel of Fortune', suit: 'major', meaning: '命运之轮转动不息，象征着生命循环中的变迁、转折与不可抗拒的机遇。轮盘之上，sphinx 掌握着上升的力量，而下降亦是旅程的一部分。这张牌预示着重要的转变即将来临——可能是突如其来的好运，也可能是推动你成长的挑战。顺势而为，不要抗拒变化的洪流，因为在每一次转动中，都蕴含着命运为你准备的新篇章。拥抱未知，相信宇宙的韵律。', meaningEn: 'The Wheel of Fortune turns ceaselessly, symbolizing the cycles of change, turning points, and irresistible opportunities in life. On the wheel, the sphinx masters ascending power while descent is also part of the journey. This card foretells that important changes are coming—possibly sudden good fortune or challenges that push your growth. Go with the flow, do not resist the torrent of change, for within every turn lies a new chapter prepared by destiny. Embrace the unknown and trust the universe\'s rhythm.', meaningReversed: '逆位的命运之轮暗示着逆境、延迟与失控感。你可能觉得命运在与你作对，计划被打乱，努力似乎付诸东流。然而，命运的低谷同样是循环的一部分，它教会你谦卑、耐心与韧性。抗拒只会加剧痛苦，接受并从中学习，才能在轮盘再次上升时飞得更高。记住：没有永恒的寒冬，转动从未停止，好运正在积蓄。', meaningReversedEn: 'The reversed Wheel of Fortune suggests adversity, delays, and feelings of losing control. You may feel that fate is working against you, plans disrupted, efforts seemingly wasted. However, the valley of fate is also part of the cycle—it teaches humility, patience, and resilience. Resistance only intensifies suffering; accept and learn from it, and you will soar higher when the wheel rises again. Remember: no winter lasts forever, and the wheel never stops turning—good fortune is gathering.', isReversed: false },
  { id: 11, name: '正义', nameEn: 'Justice', suit: 'major', meaning: '正义女神手持天平与宝剑，象征着公正、平衡与因果法则。她提醒你在做出任何决定时，都要以客观、理性的态度权衡利弊。你所播下的种子，终将结出相应的果实；而你所经历的，也必然反映着你过去的选择。这张牌预示着公正的裁决与清晰的真相即将到来。保持诚实，对自己和他人负责，因为宇宙的法则是精确而无情的。', meaningEn: 'Lady Justice holds the scales and sword, symbolizing fairness, balance, and the law of cause and effect. She reminds you to weigh pros and cons objectively and rationally in every decision. The seeds you sow will bear corresponding fruit; what you experience necessarily reflects your past choices. This card foretells that just judgment and clear truth are coming. Maintain honesty, take responsibility for yourself and others, for the universe\'s laws are precise and inexorable.', meaningReversed: '逆位的正义揭示了不公、失衡与逃避责任。你可能正在经历不公正的待遇，或是你自己在某处回避了应有的承担。偏见的阴影遮蔽了真相，而逃避只会让问题在暗处滋长。此刻需要勇敢地面对现实，纠正过去的错误，即使这意味着艰难的对质。真正的公正始于内心的诚实——对自己诚实，是重建平衡的唯一起点。', meaningReversedEn: 'The reversed Justice reveals injustice, imbalance, and逃避责任. You may be experiencing unfair treatment, or avoiding accountability yourself. The shadow of prejudice obscures truth, while逃避 only lets problems fester in darkness. Face reality bravely now, correct past mistakes, even if it means difficult confrontation. True justice begins with inner honesty—being honest with yourself is the only starting point for restoring balance.', isReversed: false },
  { id: 12, name: '倒吊人', nameEn: 'The Hanged Man', suit: 'major', meaning: '倒吊人 suspension 在树上，姿态看似被动，实则是主动选择的臣服与新视角。当挣扎与对抗已无意义，这张牌邀请你停下来，换个角度审视困局。有时候，最大的进步来自于看似的停滞；最深的领悟诞生于放手而非抓取。牺牲短暂的舒适，换取更高维的洞见。允许生命在此刻暂停，因为在悬挂的静默中，答案会以全新的面貌浮现。', meaningEn: 'The Hanged Man hangs suspended from the tree, his posture seemingly passive yet actually chosen surrender and new perspective. When struggle and resistance have become meaningless, this card invites you to pause and examine the困境 from a different angle. Sometimes the greatest progress comes from apparent stillness; the deepest insights are born from letting go rather than grasping. Sacrifice short-term comfort for higher-dimensional insight. Allow life to pause here, for in the silence of suspension, answers will emerge in entirely new forms.', meaningReversed: '逆位的倒吊人警示着固执的抗拒与无意义的牺牲。你可能死死抓住一个早已失效的策略，只因害怕承认沉没成本；或是你一直在付出，却迟迟不愿承认这种牺牲并未带来预期的回报。无谓的忍耐不是美德，而是另一种形式的逃避。是时候剪断绳索，重新掌握主动权。有些坚持是修行，有些坚持只是固执。', meaningReversedEn: 'The reversed Hanged Man warns of stubborn resistance and meaningless sacrifice. You may be clinging to a long-failed strategy, unable to admit sunk costs; or you have been giving without the sacrifice bringing expected returns. Pointless endurance is not virtue but another form of escape. It is time to cut the rope and regain initiative. Some persistence is cultivation, some is merely stubbornness.', isReversed: false },
  { id: 13, name: '死神', nameEn: 'Death', suit: 'major', meaning: '死神是塔罗中最被误解也最深刻的牌。它不代表肉体的消亡，而是象征着旧有模式的终结、蜕变与新生。一扇门正在关闭，不是惩罚，而是宇宙在为你清理空间。放手那些已经完成使命的关系、信念或生活方式，虽然告别总是伴随着痛楚，但只有彻底结束，才能迎来真正的开始。像凤凰一样，在灰烬中，你将重生得更为强大。', meaningEn: 'Death is the most misunderstood yet profound card in the tarot. It does not represent physical demise, but the end of old patterns, transformation, and rebirth. A door is closing—not as punishment, but as the universe clearing space for you. Let go of relationships, beliefs, or lifestyles that have completed their mission. Though farewell always brings pain, only through complete ending can true beginning arrive. Like the phoenix, from the ashes you will be reborn stronger.', meaningReversed: '逆位的死神揭示了抗拒改变与停滞不前的状态。你紧抓着早已死去的过去不放，害怕未知带来的不确定感。这种对终结的恐惧让你陷入一种不死不活的僵局，新的能量无法流入。然而，抗拒是自然和徒劳的——该结束的终究会结束。鼓起勇气，向过去道别。放手不是失去，而是为即将到来的新生腾出双手。', meaningReversedEn: 'The reversed Death reveals resistance to change and stagnation. You cling to the dead past, afraid of the uncertainty that change brings. This fear of ending traps you in a living-dead stalemate where new energy cannot flow. Yet resistance is natural and futile—what must end will end. Find the courage to bid farewell to the past. Letting go is not loss, but freeing both hands for the new life to come.', isReversed: false },
  { id: 14, name: '节制', nameEn: 'Temperance', suit: 'major', meaning: '节制天使站在水边，将两个杯中的水来回倾注，象征着调和、平衡与中庸之道。这不是压抑，而是让对立的力量在你的生命中和谐共舞。你可能正走在一条需要耐心与微调的道路上， extremism 只会破坏 delicate 的平衡。信任过程的流动，像水一样适应容器的形状。在给予与接受、行动与休息、理性与感性之间找到你的黄金分割点。', meaningEn: 'The Temperance angel stands by the water, pouring water back and forth between two cups, symbolizing harmony, balance, and the middle way. This is not suppression, but letting opposing forces dance harmoniously in your life. You may be on a path requiring patience and fine-tuning, where extremism will only破坏 delicate balance. Trust the flow of the process, adapt to the container\'s shape like water. Find your golden ratio between giving and receiving, action and rest, reason and emotion.', meaningReversed: '逆位的节制指向极端、失衡与过度的状态。你可能在某一方面走得太远——无论是工作、享乐、情感还是消费——而忽视了生命其他面向的需求。像一杯溢出的水，过度的倾注只会造成浪费与混乱。是时候重新审视你的优先级，找回被忽略的维度。平衡不是一次性达成的状态，而是需要持续调整的艺术。', meaningReversedEn: 'The reversed Temperance points to extremes, imbalance, and excess. You may have gone too far in one aspect—whether work, pleasure, emotion, or consumption—while neglecting other dimensions of life. Like an overflowing cup, excessive pouring only creates waste and chaos. Re-examine your priorities and找回 neglected dimensions. Balance is not a state achieved once, but an art requiring continuous adjustment.', isReversed: false },
  { id: 15, name: '恶魔', nameEn: 'The Devil', suit: 'major', meaning: '恶魔牌揭示了我们内心深处的枷锁——那些由欲望、恐惧与物质执念编织的无形锁链。牌中的人物看似被囚禁，实则锁链是松动的，他们只是遗忘了自己拥有挣脱的力量。这张牌邀请你诚实地审视：是什么在暗中控制着你的选择？是金钱、权力、成瘾的关系，还是根深蒂固的不安全感？看见枷锁，就是解脱的开始。', meaningEn: 'The Devil reveals the invisible chains within our hearts—those woven from desire, fear, and material obsession. The figures in the card seem imprisoned, yet the chains are loose; they have simply forgotten they possess the power to break free. This card invites you to honestly examine: what is secretly controlling your choices? Money, power, addictive relationships, or deep-seated insecurity? Seeing the chains is the beginning of liberation.', meaningReversed: '逆位的恶魔是觉醒与解放的号角。你终于开始意识到那些束缚你的链条其实是你自己紧抓不放的，而此刻，你正拥有打破它们的力量。无论是走出一段 toxic 的关系，戒除某种瘾癖，还是摆脱物质主义的催眠，自由的曙光已经显现。不要被惯性的恐惧拉回旧有的牢笼，勇敢地迈向属于你的解放。', meaningReversedEn: 'The reversed Devil is the trumpet of awakening and liberation. You are beginning to realize that the chains binding you are ones you yourself refuse to let go of, and you now possess the power to break them. Whether walking away from a toxic relationship, breaking an addiction, or escaping materialism\'s hypnosis, the dawn of freedom is visible. Do not let fear of the familiar pull you back into the old cage—bravely step toward your liberation.', isReversed: false },
  { id: 16, name: '塔', nameEn: 'The Tower', suit: 'major', meaning: '塔在闪电中崩塌，象征着突如其来的剧变、旧有结构的瓦解与真相的强制揭示。这虽然是一段令人震撼甚至痛苦的历程，但那些被摧毁的，本就是建立在虚假之上的脆弱幻象。宇宙以激烈的方式为你清理道路，因为温和的提醒已无法唤醒你。拥抱这场崩塌吧，因为在废墟之上，你将建造一个更为真实、坚固的自我。毁灭，是重生的前奏。', meaningEn: 'The Tower collapses in lightning, symbolizing sudden upheaval, the collapse of old structures, and the forced revelation of truth. Though this is a shocking and even painful journey, what is destroyed was built on falsehood—fragile illusions. The universe clears your path in the most intense way because gentle reminders could no longer awaken you. Embrace this collapse, for upon the ruins you will build a more authentic and solid self. Destruction is the prelude to rebirth.', meaningReversed: '逆位的塔预示着对改变的抗拒与延迟的崩塌。你可能已经感受到了裂缝的存在，却选择视而不见，用修补与妥协来维持表面的完整。然而，被压抑的风暴只会积蓄更大的能量。这张牌提醒你：主动面对并拆除那些不稳固的结构，远比等待它们灾难性地崩塌来得明智。有时候，自我拆解是一种必要的勇气。', meaningReversedEn: 'The reversed Tower foretells resistance to change and delayed collapse. You may sense the cracks yet choose to look away, maintaining surface integrity through patching and compromise. But suppressed storms only gather greater energy. This card reminds you: proactively facing and dismantling unstable structures is far wiser than waiting for catastrophic collapse. Sometimes, self-deconstruction is a necessary courage.', isReversed: false },
  { id: 17, name: '星星', nameEn: 'The Star', suit: 'major', meaning: '星星牌是风暴过后的宁静希望。 naked 的女子跪在水边，将生命之水倾倒在陆地与海洋中，象征着灵感的流淌、疗愈与对未来的信心。无论你经历了怎样的黑暗，此刻星光正穿透云层，照亮你前行的方向。保持希望，因为你的梦想并非虚无缥缈——它们正被宇宙倾听。相信直觉的指引，敞开心扉接受治愈，因为最艰难的时刻已经过去。', meaningEn: 'The Star is the quiet hope after the storm. A naked woman kneels by the water, pouring the waters of life onto land and sea, symbolizing the flow of inspiration, healing, and faith in the future. Whatever darkness you have experienced, starlight now pierces the clouds, illuminating your path forward. Maintain hope, for your dreams are not illusory—they are being heard by the universe. Trust intuitive guidance, open your heart to healing, for the hardest times have passed.', meaningReversed: '逆位的星星揭示了希望的黯淡与信心的动摇。你可能在经历了打击后陷入了悲观与绝望，觉得梦想遥不可及，甚至开始怀疑它们是否值得追寻。这种失落感是真实的，但请记住：星星从未熄灭，只是被乌云暂时遮蔽。重新点燃你内心的光，哪怕只是微弱的一点。 reconnect 与那些让你感到平静与灵感的事物，希望会重新生长。', meaningReversedEn: 'The reversed Star reveals dimming hope and shaken faith. You may have fallen into pessimism and despair after a blow, feeling dreams are out of reach, even questioning whether they are worth pursuing. This sense of loss is real, but remember: the stars have never gone out, they are merely temporarily obscured by clouds. Reignite the light within you, however faint. Reconnect with what brings you peace and inspiration, and hope will grow again.', isReversed: false },
  { id: 18, name: '月亮', nameEn: 'The Moon', suit: 'major', meaning: '月亮高悬，照亮了一条通往潜意识深处的蜿蜒小径。这是幻觉、直觉与未解恐惧的领域。你可能感到被不明朗的局势包围，真相隐藏在迷雾之中。但不要害怕黑暗，因为正是在阴影里，那些被压抑的情感与直觉才得以浮现。信任你的梦境与预感，它们比表面的现实更接近真相。穿越恐惧，你将发现内心深处不为人知的宝藏。', meaningEn: 'The Moon hangs high, illuminating a winding path toward the depths of the subconscious. This is the realm of illusion, intuition, and unresolved fears. You may feel surrounded by unclear situations, with truth hidden in fog. But do not fear the darkness, for it is in shadows that suppressed emotions and intuition surface. Trust your dreams and premonitions, for they are closer to truth than surface reality. Journey through fear, and you will discover unknown treasures deep within.', meaningReversed: '逆位的月亮标志着迷雾的散去与真相的浮现。那些曾让你夜不能寐的恐惧与幻觉，正逐渐在晨光中失去力量。然而，这也可能意味着你仍在逃避面对某些不愉快的真相，或是你的直觉被焦虑扭曲了。无论哪种情况， clarity 正在回归。勇敢地看向曾经被阴影笼罩的角落，你会发现那里并没有怪物，只有等待被理解的自己。', meaningReversedEn: 'The reversed Moon marks the dispersal of fog and the emergence of truth. The fears and illusions that once kept you awake are gradually losing power in the morning light. However, this may also mean you are still avoiding facing certain unpleasant truths, or your intuition is being distorted by anxiety. Either way, clarity is returning. Bravely look into the corners once shadowed, and you will find there are no monsters there—only yourself waiting to be understood.', isReversed: false },
  { id: 19, name: '太阳', nameEn: 'The Sun', suit: 'major', meaning: '太阳牌是塔罗中最光明的祝福。 naked 的孩童骑在白马上，手中挥舞着红旗，象征着纯粹的快乐、成功、活力与清晰的自我意识。阴霾已然散去，生命以最灿烂的姿态向你敞开。无论是事业、感情还是个人成长，这都是收获与欢庆的时刻。拥抱你的本真，像孩子一样无所畏惧地享受阳光，因为你的光芒足以温暖整个世界。', meaningEn: 'The Sun is the brightest blessing in the tarot. A naked child rides a white horse, waving a red flag, symbolizing pure joy, success, vitality, and clear self-awareness. The clouds have dispersed, and life opens to you in its most brilliant form. Whether in career, relationships, or personal growth, this is a time of harvest and celebration. Embrace your authenticity, enjoy the sunshine fearlessly like a child, for your light is warm enough to illuminate the entire world.', meaningReversed: '逆位的太阳暗示着暂时的阴霾、延迟的成功或过度的自信。乌云可能短暂地遮挡了阳光，让你怀疑光明是否还会回来；或者你可能因为小小的成就而变得傲慢，忽略了潜藏的阴影。这不是永久的黑暗，只是提醒你：即使是最耀眼的太阳，也需要尊重黑夜的存在。保持谦逊与耐心，阳光终将再次普照。', meaningReversedEn: 'The reversed Sun suggests temporary clouds, delayed success, or excessive confidence. Clouds may briefly obscure the sun, making you doubt whether light will return; or you may have become arrogant from small achievements, overlooking hidden shadows. This is not permanent darkness, just a reminder: even the brightest sun must respect the existence of night. Maintain humility and patience, and sunshine will shine again.', isReversed: false },
  { id: 20, name: '审判', nameEn: 'Judgement', suit: 'major', meaning: '审判牌描绘了大天使加百列吹响号角，灵魂从棺材中苏醒的场景。这象征着觉醒、重生与内心的召唤。你可能正站在人生的十字路口，听到来自灵魂深处的呼唤——是时候回应你真正的使命了。过去的错误已被宽恕，旧有的自我已经死亡，一个全新的你正在诞生。听从这神圣的召唤，勇敢地踏入为你准备好的新生。', meaningEn: 'Judgment depicts Archangel Gabriel blowing his trumpet, with souls awakening from coffins. This symbolizes awakening, rebirth, and the inner call. You may stand at life\'s crossroads, hearing the call from your soul\'s depths—it is time to answer your true calling. Past mistakes have been forgiven, the old self has died, and a new you is being born. Heed this divine call and bravely step into the new life prepared for you.', meaningReversed: '逆位的审判揭示了自我怀疑、逃避召唤与拒绝觉醒。你可能听到了内心深处的声音，却因为恐惧未知而选择掩耳盗铃。对过去的错误耿耿于怀，让你无法原谅自己，也就无法真正前进。或是你对他人的评判过于苛刻，反而阻碍了自己的成长。宽恕是双向的——原谅他人，也原谅自己。只有你，才能吹响自己重生的号角。', meaningReversedEn: 'The reversed Judgment reveals self-doubt,逃避 the call, and refusal to awaken. You may hear the voice from your heart\'s depths yet choose to plug your ears out of fear of the unknown. Being unable to forgive past mistakes keeps you from truly moving forward; or being overly judgmental of others反而阻碍s your own growth. Forgiveness is bidirectional—forgive others, and forgive yourself. Only you can blow the trumpet of your own rebirth.', isReversed: false },
  { id: 21, name: '世界', nameEn: 'The World', suit: 'major', meaning: '世界牌是愚人之旅的圆满终点。舞者在花环中自由旋转，手持魔杖，象征着完成、成就、整合与完美的闭环。一个重大的周期已经结束，而你已经在这个过程中收获了智慧与成长。这不是终点，而是更高层次的新起点。庆祝你的成就，享受这份圆满，因为你已经成功地整合了生命中的各种面向，准备好迈向更广阔的宇宙。', meaningEn: 'The World is the fulfilling endpoint of the Fool\'s journey. The dancer spins freely within the wreath, holding a wand, symbolizing completion, achievement, integration, and perfect closure. A major cycle has ended, and you have harvested wisdom and growth through this process. This is not the end, but a new beginning at a higher level. Celebrate your achievements, enjoy this fulfillment, for you have successfully integrated various aspects of life and are ready to step into a broader universe.', meaningReversed: '逆位的世界指向未完成、拖延与缺乏 closure 的状态。你可能在距离终点线只有一步之遥时停下了脚步，或是某个项目、关系、人生阶段迟迟无法画上句号。对完美的执念、对结束的恐惧，或是对下一个周期的焦虑，都可能让你卡在最后一步。给自己一个完整的告别，因为只有彻底结束，才能彻底开始。完成它，然后自由。', meaningReversedEn: 'The reversed World points to incompletion, procrastination, and lack of closure. You may have stopped just one step from the finish line, or a project, relationship, or life phase cannot be concluded. Attachment to perfection, fear of ending, or anxiety about the next cycle may keep you stuck at the last step. Give yourself a complete farewell, for only through complete ending can there be complete beginning. Complete it, then be free.', isReversed: false },

  // ─── Wands (权杖) ───
  { id: 22, name: '权杖王牌', nameEn: 'Ace of Wands', suit: 'wands', meaning: '权杖王牌是一团初生的火焰，代表着创意的迸发、激情的点燃与全新行动的起始。宇宙正将一个充满生命力的机会递到你的手中，它可能是一个灵感、一个项目，或是一段让你热血沸腾的关系。此刻不是犹豫的时候，让这股原始的能量引领你向前。相信你的直觉，抓住这个让你心跳加速的契机，因为火种一旦被点燃，便能照亮整片天空。', meaningEn: 'This card represents A spark of new beginning in the realm of action and passion. It brings the energy of creativity into your current situation, urging you to embrace this momentum with confidence. Trust in your ability to navigate this phase, as the ace of Wands promises growth through engagement with career.', meaningReversed: '逆位的权杖王牌暗示着创意的阻塞与行动的延迟。你可能感到一种内在的焦躁——明明有想要做的事，却总被各种阻碍拖住脚步。也许时机尚未成熟，也许你需要重新审视这个计划的基础是否稳固。不要被一时的挫折浇灭热情，而是利用这段时间打磨你的想法。当火焰准备好时，它会以更强大的力量燃烧。', meaningReversedEn: 'The reversed ace of Wands suggests blocked or delayed energy in action and passion. You may feel frustrated by obstacles or find that your enthusiasm for creativity is waning. This is a reminder to pause and reassess your approach rather than forcing progress. Look inward for what truly needs adjustment before moving forward again.', isReversed: false },
  { id: 23, name: '权杖二', nameEn: 'Two of Wands', suit: 'wands', meaning: '权杖二中的人物手握地球，站在城堡的高墙之上眺望远方。这象征着规划、远见与对未来的展望。你已经拥有了一定的基础与资源，现在需要在已知的舒适区与未知的广阔世界之间做出选择。这张牌鼓励你勇敢地踏出那一步，去探索超越现有疆域的可能性。真正的成长，永远发生在熟悉的地平线之外。', meaningEn: 'This card represents A choice or partnership in the realm of action and passion. It brings the energy of creativity into your current situation, urging you to embrace this momentum with confidence. Trust in your ability to navigate this phase, as the 2 of Wands promises growth through engagement with career.', meaningReversed: '逆位的权杖二揭示了恐惧与犹豫不决。你可能被困在对未知的过度担忧中，反复分析却迟迟不敢行动。或者，你可能过于自信地踏入了一个尚未准备好的领域，忽视了必要的规划。无论是哪种情况，此刻需要的是诚实地评估：你是真的在谨慎规划，还是仅仅在拖延？勇气不是没有恐惧，而是带着恐惧依然前行。', meaningReversedEn: 'The reversed 2 of Wands suggests blocked or delayed energy in action and passion. You may feel frustrated by obstacles or find that your enthusiasm for creativity is waning. This is a reminder to pause and reassess your approach rather than forcing progress. Look inward for what truly needs adjustment before moving forward again.', isReversed: false },
  { id: 24, name: '权杖三', nameEn: 'Three of Wands', suit: 'wands', meaning: '权杖三展现了商船从港湾驶出的画面，象征着扩展、合作与初步成果的显现。你的计划已经开始展现回报，远方的机会正在向你招手。这张牌预示着你的视野将得到拓展，可能是通过国际合作、跨领域探索，或是与志同道合者的联手。保持开放的心态，因为最好的果实往往生长在你未曾预料的土壤之中。', meaningEn: 'This card represents Collaboration and growth in the realm of action and passion. It brings the energy of creativity into your current situation, urging you to embrace this momentum with confidence. Trust in your ability to navigate this phase, as the 3 of Wands promises growth through engagement with career.', meaningReversed: '逆位的权杖三指向计划的延迟、合作的障碍与预期的落空。你可能发现远方的船队迟迟没有归来，或者你的扩展计划遭遇了意想不到的阻力。挫败感是真实的，但不要因此退缩。检查一下是否有被忽视的细节，或是沟通上的误解。有时候，延迟并非拒绝，而是宇宙在为你调整更好的时机与路径。', meaningReversedEn: 'The reversed 3 of Wands suggests blocked or delayed energy in action and passion. You may feel frustrated by obstacles or find that your enthusiasm for creativity is waning. This is a reminder to pause and reassess your approach rather than forcing progress. Look inward for what truly needs adjustment before moving forward again.', isReversed: false },
  { id: 25, name: '权杖四', nameEn: 'Four of Wands', suit: 'wands', meaning: '权杖四中鲜花与彩带装点着欢庆的拱门，象征着庆祝、和谐与稳固的基础。你可能刚刚完成一个重要的里程碑，无论是一段关系的承诺、一个项目的阶段性胜利，还是家庭的团聚，这都是值得被铭记与庆祝的时刻。在追逐更高目标的同时，不要忘记停下来，与身边的人分享这份喜悦。因为幸福不在终点，而在这些温暖的瞬间之中。', meaningEn: 'This card represents Stability and foundation in the realm of action and passion. It brings the energy of creativity into your current situation, urging you to embrace this momentum with confidence. Trust in your ability to navigate this phase, as the 4 of Wands promises growth through engagement with career.', meaningReversed: '逆位的权杖四暗示着庆祝的不完整、家庭或团队中的紧张关系。你可能在表面的欢聚之下感受到了某种不安，或是重要的里程碑被匆忙地略过，缺乏应有的 closure。也可能是你在逃避与家人、社群的连接，将自己封闭在独立的城堡里。真正的归属不是地理位置，而是心与心之间的桥梁——也许是时候修复那些断裂的纽带了。', meaningReversedEn: 'The reversed 4 of Wands suggests blocked or delayed energy in action and passion. You may feel frustrated by obstacles or find that your enthusiasm for creativity is waning. This is a reminder to pause and reassess your approach rather than forcing progress. Look inward for what truly needs adjustment before moving forward again.', isReversed: false },
  { id: 26, name: '权杖五', nameEn: 'Five of Wands', suit: 'wands', meaning: '权杖五描绘了一群年轻人手持权杖嬉戏争斗的场景，象征着冲突、竞争与能量的碰撞。你可能正处于一个充满竞争的环境之中，周围的声音嘈杂而混乱。然而，这张牌并非预示灾难，而是提醒你：适度的竞争是成长的催化剂。从混乱中找到你的位置，学习在碰撞中保持自我，因为正是在这些交锋中，你的能力被磨砺得更加锋利。', meaningEn: 'This card represents Conflict and challenge in the realm of action and passion. It brings the energy of creativity into your current situation, urging you to embrace this momentum with confidence. Trust in your ability to navigate this phase, as the 5 of Wands promises growth through engagement with career.', meaningReversed: '逆位的权杖五揭示了冲突的升级或逃避对质的倾向。你可能陷入了无意义的内耗，各方都在争夺话语权却没有真正的沟通；或者你选择了完全回避冲突，让不满在暗处发酵。这两种极端都无法带来真正的解决。这张牌邀请你：要么勇敢地面对核心矛盾，用建设性的对话替代无谓的争斗；要么，学会分辨哪些战斗根本不值得参与。', meaningReversedEn: 'The reversed 5 of Wands suggests blocked or delayed energy in action and passion. You may feel frustrated by obstacles or find that your enthusiasm for creativity is waning. This is a reminder to pause and reassess your approach rather than forcing progress. Look inward for what truly needs adjustment before moving forward again.', isReversed: false },
  { id: 27, name: '权杖六', nameEn: 'Six of Wands', suit: 'wands', meaning: '权杖六中凯旋的骑士头戴桂冠，受到人群欢呼，象征着胜利、认可与公众的成功。你的努力终于得到了应有的回报，周围的目光聚焦于你的成就。这是一个值得骄傲的时刻，但不要忘记那些在背后支持过你的人。将你的光芒分享出去，因为真正的领导力不仅在于赢得胜利，更在于激励他人相信自己也能做到。', meaningEn: 'This card represents Victory and harmony in the realm of action and passion. It brings the energy of creativity into your current situation, urging you to embrace this momentum with confidence. Trust in your ability to navigate this phase, as the 6 of Wands promises growth through engagement with career.', meaningReversed: '逆位的权杖六指向骄傲的反噬、自我怀疑与不被认可的感受。你可能经历了一个令人失望的挫折，或是发现即使你付出了全力，掌声却迟迟没有响起。不要让外界的认可定义你的价值。成功不是一条直线，每一次跌倒都是下一段飞跃的蓄力。将注意力从他人的目光移开，回归到你做事的初心——那才是最恒久的动力源泉。', meaningReversedEn: 'The reversed 6 of Wands suggests blocked or delayed energy in action and passion. You may feel frustrated by obstacles or find that your enthusiasm for creativity is waning. This is a reminder to pause and reassess your approach rather than forcing progress. Look inward for what truly needs adjustment before moving forward again.', isReversed: false },
  { id: 28, name: '权杖七', nameEn: 'Seven of Wands', suit: 'wands', meaning: '权杖七中的人物站在高地，独自对抗下方袭来的六根权杖，象征着捍卫立场、勇气与坚持。你可能正处于一个需要为自己辩护的境地，周围的人或环境都在质疑你的选择与价值。这张牌提醒你：你之所以被攻击，正是因为你占据了重要的位置。站稳你的脚跟，相信自己所建立的一切，因为你有能力守住自己的疆域。', meaningEn: 'This card represents Reflection and perseverance in the realm of action and passion. It brings the energy of creativity into your current situation, urging you to embrace this momentum with confidence. Trust in your ability to navigate this phase, as the 7 of Wands promises growth through engagement with career.', meaningReversed: '逆位的权杖七揭示了自我怀疑的侵蚀与放弃抗争的倾向。你可能在压力之下开始动摇，质疑自己是否值得这场战斗，甚至考虑放弃来之不易的阵地。有时候，退缩是智慧；但更多时候，它只是恐惧的伪装。诚实地问自己：你是因为看清了更好的道路而放手，还是因为害怕失败而逃避？真正的勇气在于，即使双腿颤抖，依然选择站立。', meaningReversedEn: 'The reversed 7 of Wands suggests blocked or delayed energy in action and passion. You may feel frustrated by obstacles or find that your enthusiasm for creativity is waning. This is a reminder to pause and reassess your approach rather than forcing progress. Look inward for what truly needs adjustment before moving forward again.', isReversed: false },
  { id: 29, name: '权杖八', nameEn: 'Eight of Wands', suit: 'wands', meaning: '八根权杖在空中飞速穿行，象征着迅猛的行动、消息的到来与势不可挡的前进动力。延迟已经结束，阻碍已经清除，能量正以你无法想象的速度汇聚并推动你向前。这是一张充满动能的牌——计划将迅速落地，消息将及时抵达，机会将一闪而过。保持警觉与敏捷，顺势而为，因为此刻的宇宙正全速站在你这边。', meaningEn: 'This card represents Swift movement and progress in the realm of action and passion. It brings the energy of creativity into your current situation, urging you to embrace this momentum with confidence. Trust in your ability to navigate this phase, as the 8 of Wands promises growth through engagement with career.', meaningReversed: '逆位的权杖八指向速度的失控、消息的延迟与方向的混乱。你可能感觉一切都进展得太快，让你无法喘息；或者相反，事情卡住了，预期的进展迟迟没有到来。无论哪种情况，此刻需要的不是更多的推力，而是暂停与校准。快速不一定等于正确，有时候放慢脚步，才能看清真正重要的目标在哪里。', meaningReversedEn: 'The reversed 8 of Wands suggests blocked or delayed energy in action and passion. You may feel frustrated by obstacles or find that your enthusiasm for creativity is waning. This is a reminder to pause and reassess your approach rather than forcing progress. Look inward for what truly needs adjustment before moving forward again.', isReversed: false },
  { id: 30, name: '权杖九', nameEn: 'Nine of Wands', suit: 'wands', meaning: '权杖九中疲惫的战士手握权杖，身上带着伤痕，却依然警觉地守望。这象征着韧性、坚持与最后的防线。你可能已经经历了一连串的挑战，身心俱疲，但最后的考验就在眼前。不要在此刻放弃——你已经走了这么远，你的经验与伤痕都是你独一无二的铠甲。再做一次深呼吸，因为这可能是黎明前最黑暗的一刻。', meaningEn: 'This card represents Independence and fulfillment in the realm of action and passion. It brings the energy of creativity into your current situation, urging you to embrace this momentum with confidence. Trust in your ability to navigate this phase, as the 9 of Wands promises growth through engagement with career.', meaningReversed: '逆位的权杖九揭示了精疲力竭与顽固的防线。你可能已经到了崩溃的边缘，却依然不肯放下手中的权杖，用最后的倔强维持着一堵早已千疮百孔的墙。这不是勇气的体现，而是不愿承认自己已经需要休息。放下不等于失败，允许自己求助、暂停、甚至暂时撤退，是为了以更完整的姿态重新出发。你的价值不取决于你承受了多少。', meaningReversedEn: 'The reversed 9 of Wands suggests blocked or delayed energy in action and passion. You may feel frustrated by obstacles or find that your enthusiasm for creativity is waning. This is a reminder to pause and reassess your approach rather than forcing progress. Look inward for what truly needs adjustment before moving forward again.', isReversed: false },
  { id: 31, name: '权杖十', nameEn: 'Ten of Wands', suit: 'wands', meaning: '权杖十中的人物背负着沉重的十根权杖，艰难地走向远方的村庄。这象征着过重的负担、责任的累积与即将到达的终点。你可能正在承担超出自己能力范围的事务，每一份责任都像一根权杖压在肩头。好消息是：村庄就在前方，你的努力即将得到回报。但首先，你需要学会分辨哪些负担是真正属于你的，哪些可以委托他人。', meaningEn: 'This card represents Completion and culmination in the realm of action and passion. It brings the energy of creativity into your current situation, urging you to embrace this momentum with confidence. Trust in your ability to navigate this phase, as the 10 of Wands promises growth through engagement with career.', meaningReversed: '逆位的权杖十指向不堪重负的崩溃与拒绝放手的执念。你可能已经到了极限，却依然在添加新的责任，仿佛只有不断地付出才能证明自己的价值。这是一个危险的循环。逆位的权杖十迫切地提醒你：放下那些不属于你的重担，学会说「不」。你不需要背负整个世界，你唯一需要负责的，是让自己活得真实而轻盈。', meaningReversedEn: 'The reversed 10 of Wands suggests blocked or delayed energy in action and passion. You may feel frustrated by obstacles or find that your enthusiasm for creativity is waning. This is a reminder to pause and reassess your approach rather than forcing progress. Look inward for what truly needs adjustment before moving forward again.', isReversed: false },
  { id: 32, name: '权杖侍从', nameEn: 'Page of Wands', suit: 'wands', meaning: '权杖侍从手持权杖，眼中闪烁着好奇与冒险的光芒，象征着探索、热情与新消息的到来。你可能正处于一个充满可能性的阶段，内心涌动着去尝试新事物的渴望。这张牌鼓励你追随这份热情，即使你还不够成熟、经验还不足——因为每一次冒险都是从第一步开始的。保持那份赤子之心，世界正等待你去发现。', meaningEn: 'This card represents New ideas and curiosity in the realm of action and passion. It brings the energy of creativity into your current situation, urging you to embrace this momentum with confidence. Trust in your ability to navigate this phase, as the page of Wands promises growth through engagement with career.', meaningReversed: '逆位的权杖侍从暗示着冲动的行为、缺乏耐心的探索与不成熟的消息。你可能被一时的热情冲昏了头脑，在没有充分准备的情况下就仓促行动，结果只能是虎头蛇尾。或者，你正在传递一个尚未成熟的想法，可能引发误解。热情是宝贵的燃料，但如果没有方向与持久力，它只会迅速燃尽。在行动之前，先让你的热情沉淀为计划。', meaningReversedEn: 'The reversed page of Wands suggests blocked or delayed energy in action and passion. You may feel frustrated by obstacles or find that your enthusiasm for creativity is waning. This is a reminder to pause and reassess your approach rather than forcing progress. Look inward for what truly needs adjustment before moving forward again.', isReversed: false },
  { id: 33, name: '权杖骑士', nameEn: 'Knight of Wands', suit: 'wands', meaning: '权杖骑士身披火焰般的盔甲，骑着骏马飞驰而出，象征着行动、冒险与无畏的追求。这是一张充满动能的牌——当灵感闪现时，你不会犹豫，而是立刻策马前行。你的热情具有感染力，你的决心足以冲破任何障碍。此刻，勇敢地去追逐那个让你心跳加速的目标吧，因为宇宙正在为你的速度让路。', meaningEn: 'This card represents Action and pursuit in the realm of action and passion. It brings the energy of creativity into your current situation, urging you to embrace this momentum with confidence. Trust in your ability to navigate this phase, as the knight of Wands promises growth through engagement with career.', meaningReversed: '逆位的权杖骑士揭示了鲁莽、冲动与缺乏耐力的追逐。你可能像一只无头苍蝇一样到处乱撞，今天对这个充满热情，明天又对那个跃跃欲试，却从未完成过任何一件事。或者，你的急躁让身边的人感到疲惫与不安。慢下来，权杖骑士。真正的征服不是看谁跑得最快，而是谁能持续地朝着同一个方向前进。', meaningReversedEn: 'The reversed knight of Wands suggests blocked or delayed energy in action and passion. You may feel frustrated by obstacles or find that your enthusiasm for creativity is waning. This is a reminder to pause and reassess your approach rather than forcing progress. Look inward for what truly needs adjustment before moving forward again.', isReversed: false },
  { id: 34, name: '权杖王后', nameEn: 'Queen of Wands', suit: 'wands', meaning: '权杖王后坐在金色的宝座上，手握权杖，身旁的黑猫象征着她的直觉与神秘力量。她是自信、热情与创造力的化身，拥有着将梦想化为现实的磁力。你内在的光芒正在吸引机会与盟友，你的自信让周围的一切都变得可能。拥抱你的力量，像太阳一样温暖地照耀他人，因为你天生就拥有点燃他人心中火焰的能力。', meaningEn: 'This card represents Nurturing and mastery in the realm of action and passion. It brings the energy of creativity into your current situation, urging you to embrace this momentum with confidence. Trust in your ability to navigate this phase, as the queen of Wands promises growth through engagement with career.', meaningReversed: '逆位的权杖王后指向自信的反噬、嫉妒与专横的倾向。你可能正用自己的光芒压制他人，将自信变成了傲慢，将热情变成了控制。或者，你正经历着自我怀疑的低谷，害怕展现真实的自己。无论是哪种极端，这张牌都在提醒你：真正的力量不需要通过打压他人来证明，而真实的自信也不需要外界的认可来维系。回归你内心的温暖源头。', meaningReversedEn: 'The reversed queen of Wands suggests blocked or delayed energy in action and passion. You may feel frustrated by obstacles or find that your enthusiasm for creativity is waning. This is a reminder to pause and reassess your approach rather than forcing progress. Look inward for what truly needs adjustment before moving forward again.', isReversed: false },
  { id: 35, name: '权杖国王', nameEn: 'King of Wands', suit: 'wands', meaning: '权杖国王端坐在他的王座上，手握权杖，身后是喷发的火山与奔跑的狮子。他是远见卓识的领导者，将激情与策略完美融合的典范。你已经具备了开创大业的能力——不仅有燃烧的愿景，更有将愿景落地的智慧。此刻，勇敢地承担领导的角色，因为你的远见与魄力，正是这个世界此刻最需要的。', meaningEn: 'This card represents Authority and leadership in the realm of action and passion. It brings the energy of creativity into your current situation, urging you to embrace this momentum with confidence. Trust in your ability to navigate this phase, as the king of Wands promises growth through engagement with career.', meaningReversed: '逆位的权杖国王揭示了专横、冲动与独裁的领导风格。你可能正在用高压与命令来推动团队，却忽视了协作与倾听的重要性；或者你的宏伟计划因为缺乏细节与执行而沦为空中楼阁。领导力不是控制，而是赋能。真正的王者知道：权力的意义在于服务他人，而非凌驾于他人之上。放下你的ego，重新赢得人心。', meaningReversedEn: 'The reversed king of Wands suggests blocked or delayed energy in action and passion. You may feel frustrated by obstacles or find that your enthusiasm for creativity is waning. This is a reminder to pause and reassess your approach rather than forcing progress. Look inward for what truly needs adjustment before moving forward again.', isReversed: false },

  // ─── Cups (圣杯) ───
  { id: 36, name: '圣杯王牌', nameEn: 'Ace of Cups', suit: 'cups', meaning: '圣杯王牌中，一只神圣的手从云中托出溢满爱的圣杯，五道水流倾泻而下，象征着情感的觉醒、爱的充盈与灵性连接的开启。这是一张关于心灵之爱的牌——新的感情、深厚的友谊、或是与宇宙源头 reconnect 的神圣时刻。打开你的心门，让爱如泉水般自由流淌，因为此刻，你的情感世界正迎来一次纯净的洗礼。', meaningEn: 'This card represents A spark of new beginning in the realm of emotions and relationships. It brings the energy of intuition into your current situation, urging you to embrace this momentum with confidence. Trust in your ability to navigate this phase, as the ace of Cups promises growth through engagement with love.', meaningReversed: '逆位的圣杯王牌暗示着情感的封闭、爱的匮乏或情绪的不稳定。你可能正经历一段内心干涸的时期，感受不到与他人的连接，甚至对自己也失去了温柔。或者，压抑已久的情感正以不健康的方式喷发。不要强迫自己立刻变得「有爱」，先从对自己诚实开始。情感的河流从未枯竭，它只是暂时被石块阻挡——清理障碍，水自会再次流淌。', meaningReversedEn: 'The reversed ace of Cups suggests blocked or delayed energy in emotions and relationships. You may feel frustrated by obstacles or find that your enthusiasm for intuition is waning. This is a reminder to pause and reassess your approach rather than forcing progress. Look inward for what truly needs adjustment before moving forward again.', isReversed: false },
  { id: 37, name: '圣杯二', nameEn: 'Two of Cups', suit: 'cups', meaning: '圣杯二中，一男一女手持圣杯相互凝视，上方缠绕着象征结合的蛇杖。这象征着真挚的伴侣关系、平等的联盟与心灵的共鸣。你可能正处于一段深刻连接的起点，无论是爱情、友情还是事业伙伴，这段关系建立在相互尊重与情感共鸣的基础之上。珍惜这份难得的默契，因为两颗心的真诚交汇，是世间最珍贵的礼物。', meaningEn: 'This card represents A choice or partnership in the realm of emotions and relationships. It brings the energy of intuition into your current situation, urging you to embrace this momentum with confidence. Trust in your ability to navigate this phase, as the 2 of Cups promises growth through engagement with love.', meaningReversed: '逆位的圣杯二揭示了关系中的失衡、不平等的付出与连接的断裂。你可能发现自己在这段关系中总是付出更多，或是双方的需求与价值观正在渐行渐远。表面的和谐掩盖了深层的裂痕，而回避只会让裂缝越来越大。诚实地面对彼此的真实感受，勇敢地表达你的需求。真正的亲密关系，始于两颗心都愿意坦诚相见。', meaningReversedEn: 'The reversed 2 of Cups suggests blocked or delayed energy in emotions and relationships. You may feel frustrated by obstacles or find that your enthusiasm for intuition is waning. This is a reminder to pause and reassess your approach rather than forcing progress. Look inward for what truly needs adjustment before moving forward again.', isReversed: false },
  { id: 38, name: '圣杯三', nameEn: 'Three of Cups', suit: 'cups', meaning: '圣杯三中三位女子高举圣杯，在丰收的果园中尽情欢庆，象征着友谊、社群的欢乐与共同的庆祝。你可能刚刚与朋友们度过了一段美好的时光，或是正在享受团队协作带来的成果。这张牌提醒你：人不是孤岛，最深的喜悦往往来自于与他人的共享。去拥抱你的社群，让欢笑声成为你们之间最坚固的纽带。', meaningEn: 'This card represents Collaboration and growth in the realm of emotions and relationships. It brings the energy of intuition into your current situation, urging you to embrace this momentum with confidence. Trust in your ability to navigate this phase, as the 3 of Cups promises growth through engagement with love.', meaningReversed: '逆位的圣杯三指向过度放纵、表面的社交与群体的疏离。你可能沉溺于无休止的派对与社交活动，却在热闹之后感到更深的空虚；或者你正被某个小团体排斥在外，感受着孤独的寒意。真正的友谊不在于聚会的频率，而在于心灵的深度。审视你的社交圈，问问自己：哪些人是你在黑暗中也会伸出手的存在？', meaningReversedEn: 'The reversed 3 of Cups suggests blocked or delayed energy in emotions and relationships. You may feel frustrated by obstacles or find that your enthusiasm for intuition is waning. This is a reminder to pause and reassess your approach rather than forcing progress. Look inward for what truly needs adjustment before moving forward again.', isReversed: false },
  { id: 39, name: '圣杯四', nameEn: 'Four of Cups', suit: 'cups', meaning: '圣杯四中，一位青年盘腿坐在树下，面前的三个圣杯视而不见，而云端伸出的手正递来第四个圣杯。这象征着情感上的倦怠、对现状的不满与对新机会的漠视。你可能正处于一段「什么都不想要」的低迷期，对曾经热爱的事物失去了兴趣。然而，宇宙从未停止向你递出新的礼物——只是你需要抬起头，才能看见那只伸向你的手。', meaningEn: 'This card represents Stability and foundation in the realm of emotions and relationships. It brings the energy of intuition into your current situation, urging you to embrace this momentum with confidence. Trust in your ability to navigate this phase, as the 4 of Cups promises growth through engagement with love.', meaningReversed: '逆位的圣杯四揭示了从倦怠中苏醒、重新发现生活热情的时刻。你可能刚刚度过了漫长的情感冬眠，现在开始感受到内心深处的渴望再次被点燃。或者，你终于意识到自己对现状的不满，并准备做出改变。无论是哪种情况，新的可能性正在向你招手。不要急于评判它们是否完美，先伸出手去触碰——因为每一个新的圣杯，都可能装着意想不到的惊喜。', meaningReversedEn: 'The reversed 4 of Cups suggests blocked or delayed energy in emotions and relationships. You may feel frustrated by obstacles or find that your enthusiasm for intuition is waning. This is a reminder to pause and reassess your approach rather than forcing progress. Look inward for what truly needs adjustment before moving forward again.', isReversed: false },
  { id: 40, name: '圣杯五', nameEn: 'Five of Cups', suit: 'cups', meaning: '圣杯五中，一位黑衣人低头注视着打翻的三个圣杯，却忽略了身后依然站立的两个。这象征着失落、悲伤与对过去的沉湎。你可能正在经历一段心碎或失望的时期，那些曾经的希望与期待如圣杯中的酒般洒落一地。悲伤是真实的，也是必要的——但请不要忘记，在你看不见的地方，依然有未被摧毁的美好等待着你转身去看见。', meaningEn: 'This card represents Conflict and challenge in the realm of emotions and relationships. It brings the energy of intuition into your current situation, urging you to embrace this momentum with confidence. Trust in your ability to navigate this phase, as the 5 of Cups promises growth through engagement with love.', meaningReversed: '逆位的圣杯五标志着疗愈的开始、走出悲伤与重新拥抱希望。你可能已经开始从失落中恢复，意识到自己不需要永远停留在哀悼之中。那些打翻的圣杯固然令人心痛，但它们不是全部的人生。逆位的圣杯五温柔地提醒你：愈合不是忘记，而是学会带着伤疤继续前行。当你准备好时，身后那两个站立的圣杯，正等待着你去品尝新的滋味。', meaningReversedEn: 'The reversed 5 of Cups suggests blocked or delayed energy in emotions and relationships. You may feel frustrated by obstacles or find that your enthusiasm for intuition is waning. This is a reminder to pause and reassess your approach rather than forcing progress. Look inward for what truly needs adjustment before moving forward again.', isReversed: false },
  { id: 41, name: '圣杯六', nameEn: 'Six of Cups', suit: 'cups', meaning: '圣杯六中，孩童们在花园中相互赠送花朵与圣杯，象征着怀旧、纯真的回忆与善意的馈赠。你可能正处于一段被美好回忆环绕的时光，或是收到了来自过去的某个温暖讯息。这张牌邀请你重新 connect 那些让你感到安全、被爱与纯真的时刻。善意是可以传递的——当你送出一份真诚的礼物，你也会在自己的心中种下一朵花。', meaningEn: 'This card represents Victory and harmony in the realm of emotions and relationships. It brings the energy of intuition into your current situation, urging you to embrace this momentum with confidence. Trust in your ability to navigate this phase, as the 6 of Cups promises growth through engagement with love.', meaningReversed: '逆位的圣杯六指向困于过去、拒绝成长与对童年的过度美化。你可能正沉溺于「过去更好」的幻觉中，用回忆的滤镜逃避当下的责任与挑战。或者，过去的某些创伤正在以隐秘的方式影响着你的现在。怀旧本身没有错，但如果它成为了你无法前行的理由，那就是一种温柔的囚禁。活在此时此地，因为此刻才是你真正拥有的一切。', meaningReversedEn: 'The reversed 6 of Cups suggests blocked or delayed energy in emotions and relationships. You may feel frustrated by obstacles or find that your enthusiasm for intuition is waning. This is a reminder to pause and reassess your approach rather than forcing progress. Look inward for what truly needs adjustment before moving forward again.', isReversed: false },
  { id: 42, name: '圣杯七', nameEn: 'Seven of Cups', suit: 'cups', meaning: '圣杯七中，七个充满幻象的圣杯漂浮在云雾之中——珠宝、城堡、龙、面具……象征着幻想、选择的诱惑与想象力的丰富。你可能正面临多个看似诱人的选项，每一个都在向你承诺不同的未来。这张牌提醒你：梦想是美好的，但不要被表面的幻象迷惑。深入审视每一个选项背后的真实代价，因为只有建立在现实基础上的梦想，才值得你去追寻。', meaningEn: 'This card represents Reflection and perseverance in the realm of emotions and relationships. It brings the energy of intuition into your current situation, urging you to embrace this momentum with confidence. Trust in your ability to navigate this phase, as the 7 of Cups promises growth through engagement with love.', meaningReversed: '逆位的圣杯七揭示了从幻想中觉醒、面对现实与做出清晰选择的时刻。云雾正在散去，那些曾让你目眩神迷的幻象开始显露出真实的面貌。你可能终于看清了某个选择的本质，决定不再沉溺于白日梦之中。这是一个清醒的时刻——虽然少了些浪漫，却多了几分踏实。将想象力与现实结合，你才能真正触摸到梦想的形状。', meaningReversedEn: 'The reversed 7 of Cups suggests blocked or delayed energy in emotions and relationships. You may feel frustrated by obstacles or find that your enthusiasm for intuition is waning. This is a reminder to pause and reassess your approach rather than forcing progress. Look inward for what truly needs adjustment before moving forward again.', isReversed: false },
  { id: 43, name: '圣杯八', nameEn: 'Eight of Cups', suit: 'cups', meaning: '圣杯八中，一位旅人转身离开精心排列的八个圣杯，向着远方的群山走去。这象征着放下、离开与追寻更深层的意义。你可能正意识到，即使拥有了许多，内心依然感到不满足。这并非不知感恩，而是灵魂在呼唤你去寻找真正属于你的东西。勇敢地转身离开吧——那些你放弃的，已经完成了它们的使命；而那些等待你的，正在更远的地方发光。', meaningEn: 'This card represents Swift movement and progress in the realm of emotions and relationships. It brings the energy of intuition into your current situation, urging you to embrace this momentum with confidence. Trust in your ability to navigate this phase, as the 8 of Cups promises growth through engagement with love.', meaningReversed: '逆位的圣杯八揭示了犹豫、恐惧改变与对离开的抗拒。你可能已经清楚地知道某段关系、某个环境或某种生活方式不再适合你，却迟迟无法迈出离开的那一步。害怕未知的孤独、对沉没成本的不舍、或是对未来的不确定，都在拉扯着你。然而，停留在一个不适合的地方，只会让你逐渐失去自我。有时候，离开不是放弃，而是对自己最深的忠诚。', meaningReversedEn: 'The reversed 8 of Cups suggests blocked or delayed energy in emotions and relationships. You may feel frustrated by obstacles or find that your enthusiasm for intuition is waning. This is a reminder to pause and reassess your approach rather than forcing progress. Look inward for what truly needs adjustment before moving forward again.', isReversed: false },
  { id: 44, name: '圣杯九', nameEn: 'Nine of Cups', suit: 'cups', meaning: '圣杯九中，一位满足的男子坐在九个排列整齐的圣杯前，脸上洋溢着幸福的微笑。这是「愿望牌」——象征着情感的满足、心愿的实现与感恩的丰盈。你可能正处于一个人生中难得的顺遂时刻，内心深处的渴望正在一一成为现实。享受这份满足，同时不要忘记感恩——因为正是你曾经播下的种子，才收获了今日的丰盛果实。', meaningEn: 'This card represents Independence and fulfillment in the realm of emotions and relationships. It brings the energy of intuition into your current situation, urging you to embrace this momentum with confidence. Trust in your ability to navigate this phase, as the 9 of Cups promises growth through engagement with love.', meaningReversed: '逆位的圣杯九指向虚荣、表面的满足与内在的空虚。你可能拥有了一切外在的成功标志——财富、地位、赞誉——但内心却依然感到一种说不清道不明的匮乏。物质的丰盛无法填补精神的空洞，他人的羡慕也无法替代真实的情感连接。这张牌邀请你：放下对「看起来幸福」的追求，去寻找那些真正让你感到活过来的事物。', meaningReversedEn: 'The reversed 9 of Cups suggests blocked or delayed energy in emotions and relationships. You may feel frustrated by obstacles or find that your enthusiasm for intuition is waning. This is a reminder to pause and reassess your approach rather than forcing progress. Look inward for what truly needs adjustment before moving forward again.', isReversed: false },
  { id: 45, name: '圣杯十', nameEn: 'Ten of Cups', suit: 'cups', meaning: '圣杯十中，一对夫妇张开双臂，十个圣杯在彩虹的拱门下绽放，象征着家庭的和谐、情感的圆满与灵魂的共振。这是一张关于无条件的爱与深层幸福的牌——你所建立的关系、家庭或社群，正在散发出最温暖的光芒。在这样的连接中，你不需要伪装，不需要表演，只需要做最真实的自己。珍惜这份天赐的和谐，因为它是生命中最珍贵的财富。', meaningEn: 'This card represents Completion and culmination in the realm of emotions and relationships. It brings the energy of intuition into your current situation, urging you to embrace this momentum with confidence. Trust in your ability to navigate this phase, as the 10 of Cups promises growth through engagement with love.', meaningReversed: '逆位的圣杯十揭示了家庭或关系中的不和、理想化的破灭与情感纽带的断裂。你可能正在经历一段亲密关系的危机，或是发现曾经完美的家庭幻象背后隐藏着裂痕。彩虹并非永恒的——它需要阳光与雨水共同作用。但这不意味着幸福是不可能的，只是提醒你需要更真实、更努力地去经营那些你最在乎的连接。修复始于坦诚的对话。', meaningReversedEn: 'The reversed 10 of Cups suggests blocked or delayed energy in emotions and relationships. You may feel frustrated by obstacles or find that your enthusiasm for intuition is waning. This is a reminder to pause and reassess your approach rather than forcing progress. Look inward for what truly needs adjustment before moving forward again.', isReversed: false },
  { id: 46, name: '圣杯侍从', nameEn: 'Page of Cups', suit: 'cups', meaning: '圣杯侍从手持圣杯，杯中跃出一条鱼，象征着情感的探索、浪漫的遐想与直觉的讯息。你可能正处于一个情感敏感的时期，梦境与直觉变得格外清晰，内心涌动着对爱与美的渴望。这张牌鼓励你：像侍从一样保持情感上的开放与好奇，不要害怕展现你的柔软与浪漫。那条跃出杯中的鱼，正是你潜意识中等待被倾听的声音。', meaningEn: 'This card represents New ideas and curiosity in the realm of emotions and relationships. It brings the energy of intuition into your current situation, urging you to embrace this momentum with confidence. Trust in your ability to navigate this phase, as the page of Cups promises growth through engagement with love.', meaningReversed: '逆位的圣杯侍从暗示着情绪化的不成熟、不切实际的幻想与直觉的扭曲。你可能正沉溺于一段一厢情愿的浪漫想象中，忽视了现实中的警示信号；或者你的情绪起伏不定，让身边的人感到无所适从。情感的敏感是天赋，但如果缺乏理性的锚定，它只会让你在情绪的海洋中随波逐流。学会在感受与思考之间找到平衡。', meaningReversedEn: 'The reversed page of Cups suggests blocked or delayed energy in emotions and relationships. You may feel frustrated by obstacles or find that your enthusiasm for intuition is waning. This is a reminder to pause and reassess your approach rather than forcing progress. Look inward for what truly needs adjustment before moving forward again.', isReversed: false },
  { id: 47, name: '圣杯骑士', nameEn: 'Knight of Cups', suit: 'cups', meaning: '圣杯骑士骑着白马，手持圣杯，缓缓向前，象征着浪漫的追求、情感的表达与诗意的旅程。你可能正处于一段充满浪漫与理想主义色彩的关系或项目中，内心涌动着对美的追求与对爱的渴望。这张牌邀请你：勇敢地追随你的心，即使道路看起来有些不切实际。因为生命中最美好的事物，往往是由那些敢于做梦的人创造出来的。', meaningEn: 'This card represents Action and pursuit in the realm of emotions and relationships. It brings the energy of intuition into your current situation, urging you to embrace this momentum with confidence. Trust in your ability to navigate this phase, as the knight of Cups promises growth through engagement with love.', meaningReversed: '逆位的圣杯骑士揭示了情感的逃避、承诺的恐惧与不切实际的理想化。你可能像一位不断追寻却从不停留的骑士，在感情中总是浅尝辄止，害怕深入的连接会带来束缚与伤害。或者，你正将某人过度理想化，将幻想中的形象投射到真实的人身上。真正的浪漫不是追逐幻影，而是有勇气看见对方的真实，并依然选择靠近。', meaningReversedEn: 'The reversed knight of Cups suggests blocked or delayed energy in emotions and relationships. You may feel frustrated by obstacles or find that your enthusiasm for intuition is waning. This is a reminder to pause and reassess your approach rather than forcing progress. Look inward for what truly needs adjustment before moving forward again.', isReversed: false },
  { id: 48, name: '圣杯王后', nameEn: 'Queen of Cups', suit: 'cups', meaning: '圣杯王后坐在海边的王座上，手捧装饰精美的圣杯，目光温柔而深邃。她是直觉、共情与无条件爱的化身。你内在的感知力正在增强，能够敏锐地捕捉到他人未说出口的情感与需求。这张牌邀请你：像圣杯王后一样，用温柔与理解去回应这个世界。你的共情不是弱点，而是照亮他人内心黑暗的一盏明灯。', meaningEn: 'This card represents Nurturing and mastery in the realm of emotions and relationships. It brings the energy of intuition into your current situation, urging you to embrace this momentum with confidence. Trust in your ability to navigate this phase, as the queen of Cups promises growth through engagement with love.', meaningReversed: '逆位的圣杯王后指向情感的过度卷入、共情的耗竭与直觉的迷失。你可能过于沉浸在他人情绪之中，以至于失去了自己的边界与中心。或者，你的直觉被焦虑与恐惧所扭曲，让你看到了并不存在的威胁。学会在倾听他人的同时保护自己的能量，在信任直觉的同时也邀请理性的参与。你的温柔需要有一个坚固的容器来承载。', meaningReversedEn: 'The reversed queen of Cups suggests blocked or delayed energy in emotions and relationships. You may feel frustrated by obstacles or find that your enthusiasm for intuition is waning. This is a reminder to pause and reassess your approach rather than forcing progress. Look inward for what truly needs adjustment before moving forward again.', isReversed: false },
  { id: 49, name: '圣杯国王', nameEn: 'King of Cups', suit: 'cups', meaning: '圣杯国王端坐在波涛汹涌的大海之上，手持圣杯，表情平静而沉稳。他是情感智慧的巅峰——既能深刻地感受，又能不被情绪所控制。你可能正处于一个需要以成熟、冷静的态度处理复杂情感局势的时刻。这张牌提醒你：真正的力量不在于压抑情感，而在于在情感的波涛中保持内心的宁静。用你的智慧与同理心去引导，而非被情绪所牵引。', meaningEn: 'This card represents Authority and leadership in the realm of emotions and relationships. It brings the energy of intuition into your current situation, urging you to embrace this momentum with confidence. Trust in your ability to navigate this phase, as the king of Cups promises growth through engagement with love.', meaningReversed: '逆位的圣杯国王揭示了情感操控、冷漠的压抑与情绪化的爆发。你可能正用理性作为盔甲，拒绝承认或表达自己的真实感受，让内心的波涛在表面之下越积越汹涌；或者你在利用自己对他人的了解来操控局面，而非真心地关怀。情感成熟不是变得冷漠，而是学会在感受与行动之间找到智慧的平衡。允许自己去感受，也允许自己去表达。', meaningReversedEn: 'The reversed king of Cups suggests blocked or delayed energy in emotions and relationships. You may feel frustrated by obstacles or find that your enthusiasm for intuition is waning. This is a reminder to pause and reassess your approach rather than forcing progress. Look inward for what truly needs adjustment before moving forward again.', isReversed: false },

  // ─── Swords (宝剑) ───
  { id: 50, name: '宝剑王牌', nameEn: 'Ace of Swords', suit: 'swords', meaning: '宝剑王牌中，一只庄严的手从云中伸出一把直指苍穹的宝剑，剑尖上戴着一顶胜利的桂冠。这象征着清晰的洞见、真理的揭示与思维力量的觉醒。你可能正处于一个念头突然通透的时刻，那些困扰你已久的迷雾被一剑劈开，真相在阳光下无所遁形。抓住这股清晰的力量，用它来斩断困惑，因为你此刻的思维锋利得足以切割任何虚妄。', meaningEn: 'This card represents A spark of new beginning in the realm of thoughts and conflicts. It brings the energy of truth into your current situation, urging you to embrace this momentum with confidence. Trust in your ability to navigate this phase, as the ace of Swords promises growth through engagement with communication.', meaningReversed: '逆位的宝剑王牌暗示着混乱的思维、错误的判断与真相的扭曲。你可能感到头脑被一团乱麻所缠绕，无法理清楚事情的脉络；或者你自以为的「真相」，其实只是偏见与误解的投射。此刻不适合做出重大决定，因为信息可能不完整，情绪可能正在干扰理性。给自己时间，让迷雾自然散去，真相会在宁静中浮现。', meaningReversedEn: 'The reversed ace of Swords suggests blocked or delayed energy in thoughts and conflicts. You may feel frustrated by obstacles or find that your enthusiasm for truth is waning. This is a reminder to pause and reassess your approach rather than forcing progress. Look inward for what truly needs adjustment before moving forward again.', isReversed: false },
  { id: 51, name: '宝剑二', nameEn: 'Two of Swords', suit: 'swords', meaning: '宝剑二中，一位蒙眼的女子双手各持一剑，交叉于胸前，身后是暗潮汹涌的海洋。这象征着艰难的选择、僵持不下的僵局与理性的僵持。你可能正处于一个两难的境地，两条路各有利弊，让你无法做出决断。这张牌提醒你：有时候，僵持本身也是一种选择——但它往往比任何决定都更消耗你的心力。摘下眼罩，勇敢地面对你所害怕看见的。', meaningEn: 'This card represents A choice or partnership in the realm of thoughts and conflicts. It brings the energy of truth into your current situation, urging you to embrace this momentum with confidence. Trust in your ability to navigate this phase, as the 2 of Swords promises growth through engagement with communication.', meaningReversed: '逆位的宝剑二揭示了逃避决策、信息的混乱与情感的介入。你可能在试图用纯粹的理性来分析一个本质上需要用心感受的问题，结果只是让事情变得更加复杂。或者，你一直回避的选择，因为拖延而变得更加紧迫。这张牌邀请你：允许情感参与决策的过程，因为人类从来不是纯粹理性的生物。你的心知道答案——倾听它。', meaningReversedEn: 'The reversed 2 of Swords suggests blocked or delayed energy in thoughts and conflicts. You may feel frustrated by obstacles or find that your enthusiasm for truth is waning. This is a reminder to pause and reassess your approach rather than forcing progress. Look inward for what truly needs adjustment before moving forward again.', isReversed: false },
  { id: 52, name: '宝剑三', nameEn: 'Three of Swords', suit: 'swords', meaning: '宝剑三中，三把利剑刺穿一颗红心，天空中下着雨，象征着心碎、悲伤与痛苦的真相。你可能正在经历一段极其痛苦的时期——背叛、分离、失落，或是一个残酷的事实刺穿了你对某段关系或某个信念的期待。这张牌不会粉饰太平：痛苦是真实的，伤口是深刻的。但它也在告诉你：只有在痛苦中，我们才能真正看见自己的心。允许自己去悲伤，因为每一次心碎，都是灵魂成长的一部分。', meaningEn: 'This card represents Collaboration and growth in the realm of thoughts and conflicts. It brings the energy of truth into your current situation, urging you to embrace this momentum with confidence. Trust in your ability to navigate this phase, as the 3 of Swords promises growth through engagement with communication.', meaningReversed: '逆位的宝剑三标志着从心碎中复苏、痛苦的缓解与疗愈的开始。伤口依然存在，但鲜血已经止住，你正在学会带着伤疤继续生活。你可能正在从一段痛苦的经历中慢慢走出，重新找回内心的平静。不要急于「完全好起来」——愈合是一个过程，不是目的地。给自己足够的时间和空间，温柔地对待自己，因为你的心比你想象的更有韧性。', meaningReversedEn: 'The reversed 3 of Swords suggests blocked or delayed energy in thoughts and conflicts. You may feel frustrated by obstacles or find that your enthusiasm for truth is waning. This is a reminder to pause and reassess your approach rather than forcing progress. Look inward for what truly needs adjustment before moving forward again.', isReversed: false },
  { id: 53, name: '宝剑四', nameEn: 'Four of Swords', suit: 'swords', meaning: '宝剑四中，一位骑士静静地躺在教堂的祭坛上，双手交叠，三把宝剑悬挂在墙上，第四把置于身下。这象征着休息、恢复与内心的宁静。你可能刚刚经历了一段高强度的精神消耗——无论是工作的压力、情感的风暴还是思维的过度运转。此刻，宇宙在温柔地命令你：停下来，休息，让身心得到修复。真正的力量不是永不停歇，而是懂得在适当的时候闭上双眼，让灵魂在静默中充电。', meaningEn: 'This card represents Stability and foundation in the realm of thoughts and conflicts. It brings the energy of truth into your current situation, urging you to embrace this momentum with confidence. Trust in your ability to navigate this phase, as the 4 of Swords promises growth through engagement with communication.', meaningReversed: '逆位的宝剑四揭示了过度休息导致的停滞、从退缩中苏醒与重新投入行动的必要。你可能已经休息了太久，以至于休息本身变成了一种逃避。或者，你在该休息的时候强迫自己继续运转，拒绝了身体发出的求救信号。找到平衡点——休息是为了更好地前行，而不是为了永远停留。当你感到能量恢复时，是时候睁开眼睛，重新拿起你的剑了。', meaningReversedEn: 'The reversed 4 of Swords suggests blocked or delayed energy in thoughts and conflicts. You may feel frustrated by obstacles or find that your enthusiasm for truth is waning. This is a reminder to pause and reassess your approach rather than forcing progress. Look inward for what truly needs adjustment before moving forward again.', isReversed: false },
  { id: 54, name: '宝剑五', nameEn: 'Five of Swords', suit: 'swords', meaning: '宝剑五中，一位男子手持三把宝剑，俯视着两名败退的对手，天空阴沉。这象征着冲突的胜利、不择手段的竞争与空洞的 triumph。你可能刚刚在某个争斗中「赢了」，但胜利的滋味却异常苦涩。这张牌提醒你审视：这场胜利值得吗？你是否为了赢而牺牲了更重要的东西——信任、关系、或是自己的 integrity？有时候，放弃战斗比赢得战斗需要更大的勇气。', meaningEn: 'This card represents Conflict and challenge in the realm of thoughts and conflicts. It brings the energy of truth into your current situation, urging you to embrace this momentum with confidence. Trust in your ability to navigate this phase, as the 5 of Swords promises growth through engagement with communication.', meaningReversed: '逆位的宝剑五指向冲突的和解、放下执念与修复关系的契机。你可能意识到某场争斗本身就是无意义的，决定放下武器，寻求和平的解决方案。或者，你正在从一次「惨胜」中反思，意识到自己付出了过高的代价。逆位的宝剑五是一扇和解之门——它邀请你放下ego，主动伸出橄榄枝。真正的胜利，是让所有人都能带着尊严离开战场。', meaningReversedEn: 'The reversed 5 of Swords suggests blocked or delayed energy in thoughts and conflicts. You may feel frustrated by obstacles or find that your enthusiasm for truth is waning. This is a reminder to pause and reassess your approach rather than forcing progress. Look inward for what truly needs adjustment before moving forward again.', isReversed: false },
  { id: 55, name: '宝剑六', nameEn: 'Six of Swords', suit: 'swords', meaning: '宝剑六中，一位摆渡人载着乘客与六把宝剑，小船正驶向平静的对岸。这象征着过渡、离开困境与前往更平静的彼岸。你可能正处于一个人生的转折期，虽然还带着过去的伤痕与记忆，但你正在主动选择离开那个让你痛苦的环境。前方的彼岸已经清晰可见，虽然航行的过程不会完全没有波澜，但你要知道：最艰难的部分已经在你身后了。', meaningEn: 'This card represents Victory and harmony in the realm of thoughts and conflicts. It brings the energy of truth into your current situation, urging you to embrace this momentum with confidence. Trust in your ability to navigate this phase, as the 6 of Swords promises growth through engagement with communication.', meaningReversed: '逆位的宝剑六揭示了过渡的困难、不愿离开旧有困境与对改变的抗拒。你可能已经意识到了需要离开，却总是被各种理由拖住脚步——对未知的恐惧、对过去的不舍、或是尚未处理完的情绪包袱。小船无法靠岸，因为你还没有真正准备好启程。给自己时间去告别，但不要让告别变成永恒的停留。对岸的平静，正在等待你划动第一桨。', meaningReversedEn: 'The reversed 6 of Swords suggests blocked or delayed energy in thoughts and conflicts. You may feel frustrated by obstacles or find that your enthusiasm for truth is waning. This is a reminder to pause and reassess your approach rather than forcing progress. Look inward for what truly needs adjustment before moving forward again.', isReversed: false },
  { id: 56, name: '宝剑七', nameEn: 'Seven of Swords', suit: 'swords', meaning: '宝剑七中，一名男子偷偷摸摸地抱着五把宝剑，留下两把，脸上带着狡黠的表情。这象征着策略、机智与不那么光明正大的手段。你可能正处于一个需要运用智慧与策略来应对复杂局面的时刻。这张牌并不直接评判你的方法，而是提醒你：每一个选择都有代价。如果你选择了捷径或隐秘的方式，请确保你能够承担相应的后果。有时候，巧计是必要的；但永远不要用自欺来替代真正的解决方案。', meaningEn: 'This card represents Reflection and perseverance in the realm of thoughts and conflicts. It brings the energy of truth into your current situation, urging you to embrace this momentum with confidence. Trust in your ability to navigate this phase, as the 7 of Swords promises growth through engagement with communication.', meaningReversed: '逆位的宝剑七揭示了计谋的败露、自欺的终结与重新选择诚实的道路。你可能发现自己的某个策略适得其反，秘密被揭开，或是终于意识到自己一直在欺骗的其实是自己。这是一个令人不安却必要的觉醒时刻。逆位的宝剑七邀请你：放下那些精巧的算计，用诚实与透明来面对问题。真相可能会痛，但它是唯一能让你真正自由的道路。', meaningReversedEn: 'The reversed 7 of Swords suggests blocked or delayed energy in thoughts and conflicts. You may feel frustrated by obstacles or find that your enthusiasm for truth is waning. This is a reminder to pause and reassess your approach rather than forcing progress. Look inward for what truly needs adjustment before moving forward again.', isReversed: false },
  { id: 57, name: '宝剑八', nameEn: 'Eight of Swords', suit: 'swords', meaning: '宝剑八中，一位被蒙眼的女子被绳索捆绑，周围插着八把宝剑，看似被困，但她脚边的水却浅得可以轻易走出。这象征着自我设限、恐惧制造的牢笼与感知的囚徒。你可能觉得自己被困住了，但请仔细审视：那些困住你的「墙」，有多少是真正存在的，又有多少只是你内心的恐惧所投射出的幻象？你手中的束缚其实松散得可以轻易挣脱——只需要你愿意摘下眼罩，看见真相。', meaningEn: 'This card represents Swift movement and progress in the realm of thoughts and conflicts. It brings the energy of truth into your current situation, urging you to embrace this momentum with confidence. Trust in your ability to navigate this phase, as the 8 of Swords promises growth through engagement with communication.', meaningReversed: '逆位的宝剑八标志着觉醒、挣脱束缚与重获自由的开始。你可能刚刚意识到，自己一直以为是牢笼的东西，其实只是纸糊的围墙。恐惧的迷雾正在散去，你开始看清自己其实一直拥有选择的力量。这是一个解放的时刻——虽然走出舒适区的第一步可能会让你感到不安，但没有什么比亲手打破自己建造的牢笼更令人自由的了。', meaningReversedEn: 'The reversed 8 of Swords suggests blocked or delayed energy in thoughts and conflicts. You may feel frustrated by obstacles or find that your enthusiasm for truth is waning. This is a reminder to pause and reassess your approach rather than forcing progress. Look inward for what truly needs adjustment before moving forward again.', isReversed: false },
  { id: 58, name: '宝剑九', nameEn: 'Nine of Swords', suit: 'swords', meaning: '宝剑九中，一个人从噩梦中惊醒，双手掩面，墙上悬挂着九把剑。这是塔罗中最令人不安的牌之一，象征着极度的焦虑、恐惧与精神上的折磨。你可能正在经历一段难以入眠的夜晚，心中的忧虑如循环播放的噩梦般挥之不去。这张牌不会轻视你的痛苦——它知道那种深夜的孤独与恐惧有多么真实。但它也在告诉你：这些剑只是挂在墙上，并没有真正刺向你。黎明终会到来，而你会发现，你所害怕的怪兽，在日光下只是阴影。', meaningEn: 'This card represents Independence and fulfillment in the realm of thoughts and conflicts. It brings the energy of truth into your current situation, urging you to embrace this momentum with confidence. Trust in your ability to navigate this phase, as the 9 of Swords promises growth through engagement with communication.', meaningReversed: '逆位的宝剑九指向焦虑的缓解、走出噩梦与重新找回内心平静的可能。你可能开始意识到，那些让你彻夜难眠的恐惧，很大程度上是被你的想象力放大了。或者，你正在学习用更健康的方式来处理压力与忧虑——冥想、倾诉、专业帮助。无论如何，最深的黑暗已经过去。不要独自承受，伸出手去寻求帮助，因为你值得被温柔以待。', meaningReversedEn: 'The reversed 9 of Swords suggests blocked or delayed energy in thoughts and conflicts. You may feel frustrated by obstacles or find that your enthusiasm for truth is waning. This is a reminder to pause and reassess your approach rather than forcing progress. Look inward for what truly needs adjustment before moving forward again.', isReversed: false },
  { id: 59, name: '宝剑十', nameEn: 'Ten of Swords', suit: 'swords', meaning: '宝剑十中，一个人俯卧在地，背上插着十把剑，天空却露出了黎明的曙光。这象征着彻底的结束、崩溃与最低点的到来。你可能正经历着一段极其痛苦的终结——某个梦想、某段关系、或是某种自我认同的彻底崩塌。这是最黑暗的时刻，但也是塔罗中最充满希望的时刻之一。因为当一切都已经瓦解，没有更多可以失去的时候，重建就已经开始了。黎明总是在最深的黑夜之后到来。', meaningEn: 'This card represents Completion and culmination in the realm of thoughts and conflicts. It brings the energy of truth into your current situation, urging you to embrace this momentum with confidence. Trust in your ability to navigate this phase, as the 10 of Swords promises growth through engagement with communication.', meaningReversed: '逆位的宝剑十揭示了在彻底崩溃边缘的挣扎、不愿接受结束与对重生的抗拒。你可能正试图用最后的力量维持一个已经死去的局面，害怕面对「一切已经结束」的事实。但逆位的宝剑十提醒你：有时候，我们需要先让自己完全倒下，才能真正站起来。接受这个结束，不是软弱，而是对自己最大的慈悲。因为只有在废墟之上，新的生命才能破土而出。', meaningReversedEn: 'The reversed 10 of Swords suggests blocked or delayed energy in thoughts and conflicts. You may feel frustrated by obstacles or find that your enthusiasm for truth is waning. This is a reminder to pause and reassess your approach rather than forcing progress. Look inward for what truly needs adjustment before moving forward again.', isReversed: false },
  { id: 60, name: '宝剑侍从', nameEn: 'Page of Swords', suit: 'swords', meaning: '宝剑侍从手持宝剑，站在风中，目光锐利而充满好奇，象征着求知欲、敏锐的观察与新思想的萌芽。你可能正处于一个信息爆炸的阶段，新想法如疾风般涌入你的脑海，让你兴奋得难以入眠。这张牌鼓励你：保持这份对真相的渴望与对知识的好奇，像侦探一样去观察、去质疑、去探索。你的思维正在快速成长期，每一个新的洞见都在塑造一个更清晰的你看待世界的方式。', meaningEn: 'This card represents New ideas and curiosity in the realm of thoughts and conflicts. It brings the energy of truth into your current situation, urging you to embrace this momentum with confidence. Trust in your ability to navigate this phase, as the page of Swords promises growth through engagement with communication.', meaningReversed: '逆位的宝剑侍从暗示着流言蜚语、不加思考的言辞与信息过载的混乱。你可能正在不假思索地传播某些未经证实的消息，或是被网络上铺天盖地的信息弄得头昏脑胀。年轻的宝剑侍从需要学会：话语是双刃剑，说出之前请先思考。在急于表达之前，给自己一点时间沉淀。真相不需要匆忙，它经得起等待。', meaningReversedEn: 'The reversed page of Swords suggests blocked or delayed energy in thoughts and conflicts. You may feel frustrated by obstacles or find that your enthusiasm for truth is waning. This is a reminder to pause and reassess your approach rather than forcing progress. Look inward for what truly needs adjustment before moving forward again.', isReversed: false },
  { id: 61, name: '宝剑骑士', nameEn: 'Knight of Swords', suit: 'swords', meaning: '宝剑骑士身披盔甲，高举宝剑，骑着骏马如闪电般冲锋，象征着果断的行动、强烈的决心与一往无前的勇气。当你决定了一件事，你不会犹豫，不会回头，而是直接冲向目标。这股能量是宝贵的——在太多人瞻前顾后的时候，你的果断本身就是一种力量。但请记住：最快的剑不一定是最精准的剑。在冲锋的同时，偶尔抬头看看方向，确保你冲向你真正想去的地方。', meaningEn: 'This card represents Action and pursuit in the realm of thoughts and conflicts. It brings the energy of truth into your current situation, urging you to embrace this momentum with confidence. Trust in your ability to navigate this phase, as the knight of Swords promises growth through engagement with communication.', meaningReversed: '逆位的宝剑骑士揭示了鲁莽的冲动、言语的攻击性与缺乏耐性的破坏力。你可能像一只失控的犀牛，所到之处留下一片狼藉，却还觉得自己只是在「追求真相」或「捍卫正义」。你的话语可能伤人，你的行动可能破坏了你本想保护的东西。停下来，深呼吸。真正的勇气不是横冲直撞，而是在愤怒与冲动面前选择停顿三秒。', meaningReversedEn: 'The reversed knight of Swords suggests blocked or delayed energy in thoughts and conflicts. You may feel frustrated by obstacles or find that your enthusiasm for truth is waning. This is a reminder to pause and reassess your approach rather than forcing progress. Look inward for what truly needs adjustment before moving forward again.', isReversed: false },
  { id: 62, name: '宝剑王后', nameEn: 'Queen of Swords', suit: 'swords', meaning: '宝剑王后端坐于王座，手持宝剑，目光如炬，头顶是飞翔的鸟儿，象征着清晰的头脑、独立的判断与诚实的沟通。她是智慧与真相的守护者，不惧怕说出别人不愿听的话，因为她深知：虚假的温柔比残酷的真相更具毁灭性。你可能正处于一个需要以清明、理性的态度面对复杂局势的时刻。像宝剑王后一样，用你锐利的洞察力穿透表象，但永远不要忘记，你的剑是为了守护，而非伤害。', meaningEn: 'This card represents Nurturing and mastery in the realm of thoughts and conflicts. It brings the energy of truth into your current situation, urging you to embrace this momentum with confidence. Trust in your ability to navigate this phase, as the queen of Swords promises growth through engagement with communication.', meaningReversed: '逆位的宝剑王后指向冷酷的批判、情感隔离与用理性作为武器的伤害。你可能正在用「我只是说实话」作为盾牌，说出一些伤人的话，却拒绝承认自己的言语带来的痛苦。或者，你过度依赖逻辑，完全关闭了自己的情感通道，让身边的人感到无法靠近。智慧的剑需要有温度的手来握——在说出真相的同时，也请记住温柔的力量。', meaningReversedEn: 'The reversed queen of Swords suggests blocked or delayed energy in thoughts and conflicts. You may feel frustrated by obstacles or find that your enthusiasm for truth is waning. This is a reminder to pause and reassess your approach rather than forcing progress. Look inward for what truly needs adjustment before moving forward again.', isReversed: false },
  { id: 63, name: '宝剑国王', nameEn: 'King of Swords', suit: 'swords', meaning: '宝剑国王端坐于他的王座，手握直立的宝剑，目光深邃而坚定，象征着权威的智慧、公正的裁决与成熟的理性。他是思维力量的巅峰——既能看透事物的本质，又能以公正与慈悲来运用这份洞见。你可能正处于一个需要做出重大决策的时刻，或是在一个需要清晰领导力的位置上。像宝剑国王一样，让理性成为你的剑，让公正成为你的盾，你将引领众人穿越迷雾，抵达真相的彼岸。', meaningEn: 'This card represents Authority and leadership in the realm of thoughts and conflicts. It brings the energy of truth into your current situation, urging you to embrace this momentum with confidence. Trust in your ability to navigate this phase, as the king of Swords promises growth through engagement with communication.', meaningReversed: '逆位的宝剑国王揭示了独裁的理性、冷漠的权威与滥用权力的危险。你可能正在用「为了大家好」或「这是理性的选择」来为自己的专断辩护，却忽视了决策背后真实的人性与情感。或者，你被自己的逻辑困住，变得僵化而无法接受新的视角。真正的智慧在于知道理性的边界在哪里——在逻辑之外，还有人心，还有那些无法被计算的价值。', meaningReversedEn: 'The reversed king of Swords suggests blocked or delayed energy in thoughts and conflicts. You may feel frustrated by obstacles or find that your enthusiasm for truth is waning. This is a reminder to pause and reassess your approach rather than forcing progress. Look inward for what truly needs adjustment before moving forward again.', isReversed: false },

  // ─── Pentacles (星币) ───
  { id: 64, name: '星币王牌', nameEn: 'Ace of Pentacles', suit: 'pentacles', meaning: '星币王牌中，一只神圣的手从云中托出一枚金光闪闪的星币，下方是繁花盛开的花园与通往远方的拱门。这象征着物质层面的新机遇、财富的种子与实际的回报。宇宙正在将一个具体的、可以触摸的机会送到你的门前——可能是一份新工作、一笔投资、或是一个能够带来稳定收益的项目。这是一张关于现实世界的牌，提醒你将梦想转化为可执行的计划，因为种子只有埋入土壤，才能发芽。', meaningEn: 'This card represents A spark of new beginning in the realm of material world and work. It brings the energy of money into your current situation, urging you to embrace this momentum with confidence. Trust in your ability to navigate this phase, as the ace of Pentacles promises growth through engagement with health.', meaningReversed: '逆位的星币王牌暗示着错失的物质机遇、财务上的不明智决策与对物质目标的过度执着。你可能因为犹豫而错过了某个重要的机会，或是在没有充分评估风险的情况下匆忙投入。或者，你可能将所有注意力都放在金钱与物质上，却忽视了生命中那些无法用数字衡量的价值。财富本身不是目的，它只是让你活得更加自由的工具之一。', meaningReversedEn: 'The reversed ace of Pentacles suggests blocked or delayed energy in material world and work. You may feel frustrated by obstacles or find that your enthusiasm for money is waning. This is a reminder to pause and reassess your approach rather than forcing progress. Look inward for what truly needs adjustment before moving forward again.', isReversed: false },
  { id: 65, name: '星币二', nameEn: 'Two of Pentacles', suit: 'pentacles', meaning: '星币二中，一位杂耍艺人在波涛汹涌的海面上，灵巧地抛接两枚星币，象征着平衡、多任务处理与生活中的 juggling。你可能正处于一个需要同时管理多个事务的阶段——工作与生活、多项项目、或是不同角色之间的切换。这张牌提醒你：灵活与适应能力是你此刻最大的资产。像杂耍艺人一样，保持节奏与幽默感，即使脚下波涛汹涌，你依然可以在变动中找到属于自己的平衡点。', meaningEn: 'This card represents A choice or partnership in the realm of material world and work. It brings the energy of money into your current situation, urging you to embrace this momentum with confidence. Trust in your ability to navigate this phase, as the 2 of Pentacles promises growth through engagement with health.', meaningReversed: '逆位的星币二揭示了失衡、 overwhelmed 与无法兼顾的困境。你可能正被太多的责任压得喘不过气，手中的星币一个接一个地掉落。或者，你在不同的选择之间摇摆不定，既放不下这个，又舍不得那个，结果什么都做不好。此刻需要的不是更多的努力，而是勇敢的取舍。承认自己的有限，放下那些不再服务于你的球，你才能重新找回平衡。', meaningReversedEn: 'The reversed 2 of Pentacles suggests blocked or delayed energy in material world and work. You may feel frustrated by obstacles or find that your enthusiasm for money is waning. This is a reminder to pause and reassess your approach rather than forcing progress. Look inward for what truly needs adjustment before moving forward again.', isReversed: false },
  { id: 66, name: '星币三', nameEn: 'Three of Pentacles', suit: 'pentacles', meaning: '星币三中，一位工匠在教堂中雕刻，身旁站着两位顾问，象征着团队合作、技艺的精进与专业认可。你可能正处于一个需要与他人协作完成重要项目的阶段，或是你的专业技能正在得到他人的赏识与尊重。这张牌提醒你：伟大的作品很少由一个人独自完成。学会欣赏他人的专长，谦虚地接受反馈，因为你的作品将在众人的智慧与努力下，变得更加卓越。', meaningEn: 'This card represents Collaboration and growth in the realm of material world and work. It brings the energy of money into your current situation, urging you to embrace this momentum with confidence. Trust in your ability to navigate this phase, as the 3 of Pentacles promises growth through engagement with health.', meaningReversed: '逆位的星币三指向团队中的不和、技艺的不足与对专业意见的抗拒。你可能正与一个缺乏默契的团队共事，各方各执己见，无法形成有效的协作；或者你过于自信，拒绝听取那些本可以帮助你提升的建议。真正的 mastery 不是无所不知，而是永远保持学徒的心态。放下骄傲，向他人学习——因为你周围的每一个人，都可能成为你最好的老师。', meaningReversedEn: 'The reversed 3 of Pentacles suggests blocked or delayed energy in material world and work. You may feel frustrated by obstacles or find that your enthusiasm for money is waning. This is a reminder to pause and reassess your approach rather than forcing progress. Look inward for what truly needs adjustment before moving forward again.', isReversed: false },
  { id: 67, name: '星币四', nameEn: 'Four of Pentacles', suit: 'pentacles', meaning: '星币四中，一位男子紧紧抱着四枚星币，脚踩两枚，头顶一枚，胸口还抱着一枚，象征着对物质的执着、保守与安全的焦虑。你可能正处于一个对财务安全过度担忧的阶段，紧紧抓住已有的资源，害怕任何流失的可能性。这张牌提醒你：适度的谨慎是明智的，但过度的囤积只会让你成为自己财富的囚徒。真正的安全感不是来自于拥有多少，而是来自于相信自己无论失去什么，都有能力重新创造。', meaningEn: 'This card represents Stability and foundation in the realm of material world and work. It brings the energy of money into your current situation, urging you to embrace this momentum with confidence. Trust in your ability to navigate this phase, as the 4 of Pentacles promises growth through engagement with health.', meaningReversed: '逆位的星币四标志着从物质执着中解放、学会放手与重新流动。你可能正在意识到，过度的控制与囤积并没有给你带来真正的安全，反而让你陷入了焦虑与孤立的循环。或者，你正在学习更慷慨地分享自己的资源——无论是金钱、时间还是爱。放手不是失去，而是让能量重新流动。当你愿意给予，宇宙会以意想不到的方式回馈你。', meaningReversedEn: 'The reversed 4 of Pentacles suggests blocked or delayed energy in material world and work. You may feel frustrated by obstacles or find that your enthusiasm for money is waning. This is a reminder to pause and reassess your approach rather than forcing progress. Look inward for what truly needs adjustment before moving forward again.', isReversed: false },
  { id: 68, name: '星币五', nameEn: 'Five of Pentacles', suit: 'pentacles', meaning: '星币五中，两个衣衫褴褛的人在风雪中艰难前行，经过一扇透出温暖光芒的教堂窗户，却似乎并未注意到身后的庇护所。这象征着物质上的匮乏、困难时期与对帮助的视而不见。你可能正在经历一段经济或资源上的低谷，感到寒冷、孤独与无助。但请仔细看看——那扇温暖的窗户就在你身后，只是你的目光被前方的风雪所遮蔽。允许自己去求助，去敲门，因为援助从未远离，它只是在等待你转过身来。', meaningEn: 'This card represents Conflict and challenge in the realm of material world and work. It brings the energy of money into your current situation, urging you to embrace this momentum with confidence. Trust in your ability to navigate this phase, as the 5 of Pentacles promises growth through engagement with health.', meaningReversed: '逆位的星币五指向困难的缓解、走出匮乏与重新发现身边的资源。你可能刚刚度过了最艰难的时期，开始看到转机出现。或者，你终于意识到，即使在最低谷的时候，你也从未真正独自一人——只是你一直太骄傲或太害怕，没有去敲那扇门。逆位的星币五温柔地提醒你：接受帮助不是软弱，而是对生命的信任。当你愿意承认自己需要帮助时，帮助就已经在路上了。', meaningReversedEn: 'The reversed 5 of Pentacles suggests blocked or delayed energy in material world and work. You may feel frustrated by obstacles or find that your enthusiasm for money is waning. This is a reminder to pause and reassess your approach rather than forcing progress. Look inward for what truly needs adjustment before moving forward again.', isReversed: false },
  { id: 69, name: '星币六', nameEn: 'Six of Pentacles', suit: 'pentacles', meaning: '星币六中，一位富有的商人手持天平，向跪地的乞者分发金币，象征着慷慨、互惠与资源的流动。你可能正处于一个可以给予他人的位置，或是正在收到来自他人的帮助。这张牌提醒你：财富与资源的真正价值在于流动。当你给予时，你确认了自身的丰盛；当你接受时，你给予了他人行善的机会。施与受是一个循环的两面，缺一不可。在这个循环中，没有高位与低位，只有人与人之间的连接。', meaningEn: 'This card represents Victory and harmony in the realm of material world and work. It brings the energy of money into your current situation, urging you to embrace this momentum with confidence. Trust in your ability to navigate this phase, as the 6 of Pentacles promises growth through engagement with health.', meaningReversed: '逆位的星币六揭示了给予的不平衡、附带条件的慷慨与对接受的抗拒。你可能正在给予，但内心期望着回报；或者你接受的援助让你感到负债与羞耻，破坏了关系的平等性。也可能，你正被一个不平等的权力动态所困——无论是作为给予者还是接受者。真正的慷慨不求回报，真正的接受不感亏欠。审视这段关系中的天平，它是否真的平衡？', meaningReversedEn: 'The reversed 6 of Pentacles suggests blocked or delayed energy in material world and work. You may feel frustrated by obstacles or find that your enthusiasm for money is waning. This is a reminder to pause and reassess your approach rather than forcing progress. Look inward for what truly needs adjustment before moving forward again.', isReversed: false },
  { id: 70, name: '星币七', nameEn: 'Seven of Pentacles', suit: 'pentacles', meaning: '星币七中，一位农夫拄着锄头，凝望着藤蔓上即将成熟的七枚星币，象征着耐心的等待、对成果的评估与长期投资。你可能正处于一个项目的中间阶段，付出了大量的努力，却尚未看到明显的回报。这张牌提醒你：成长需要时间，果实需要季节。不要在此刻急于收割，因为你的耐心即将得到回报。同时，这也是评估的时刻——你的努力是否花在了正确的方向上？调整还来得及。', meaningEn: 'This card represents Reflection and perseverance in the realm of material world and work. It brings the energy of money into your current situation, urging you to embrace this momentum with confidence. Trust in your ability to navigate this phase, as the 7 of Pentacles promises growth through engagement with health.', meaningReversed: '逆位的星币七指向焦虑的等待、对成果的不耐烦与错误方向的坚持。你可能对自己的努力感到沮丧，觉得付出了这么多却看不到希望；或者你正在一棵不会结果的树上继续浇水，因为沉没成本让你无法放手。逆位的星币七邀请你诚实地审视：你是在耐心地等待花开，还是只是不敢承认走错了路？有时候，最大的勇气是在恰当的时机选择改变方向。', meaningReversedEn: 'The reversed 7 of Pentacles suggests blocked or delayed energy in material world and work. You may feel frustrated by obstacles or find that your enthusiasm for money is waning. This is a reminder to pause and reassess your approach rather than forcing progress. Look inward for what truly needs adjustment before moving forward again.', isReversed: false },
  { id: 71, name: '星币八', nameEn: 'Eight of Pentacles', suit: 'pentacles', meaning: '星币八中，一位工匠专注地雕刻着星币，身旁已经整齐排列着七枚完成的作品。这象征着勤奋、技能的精进与对卓越的专注追求。你可能正处于一个需要埋头苦干、打磨技艺的阶段。这不是一个 glamorous 的时刻，但却是建立长期价值的基石。每一枚你精心雕琢的星币，都在为你的未来积累声誉与能力。保持专注，因为 mastery 不是天赋的馈赠，而是日复一日重复的结果。', meaningEn: 'This card represents Swift movement and progress in the realm of material world and work. It brings the energy of money into your current situation, urging you to embrace this momentum with confidence. Trust in your ability to navigate this phase, as the 8 of Pentacles promises growth through engagement with health.', meaningReversed: '逆位的星币八揭示了倦怠、缺乏动力与工作与生活失衡。你可能感到自己的努力陷入了一种机械的重复，失去了最初的热情与意义；或者你过度工作，以至于忽视了生命中其他重要的维度。技能的精进固然重要，但如果它让你失去了对生活的热爱，那它的意义又何在？停下来，问问自己：你工作是为了生活，还是活着只是为了工作？', meaningReversedEn: 'The reversed 8 of Pentacles suggests blocked or delayed energy in material world and work. You may feel frustrated by obstacles or find that your enthusiasm for money is waning. This is a reminder to pause and reassess your approach rather than forcing progress. Look inward for what truly needs adjustment before moving forward again.', isReversed: false },
  { id: 72, name: '星币九', nameEn: 'Nine of Pentacles', suit: 'pentacles', meaning: '星币九中，一位优雅的女士站在繁茂的花园中，身后是九枚成熟的星币，一只猎鹰栖息在她的手上。这象征着物质上的独立、自给自足与享受丰盛果实的能力。你可能正处于一个人生中难得的富足时刻——不是炫耀的财富，而是一种内心深处的安稳与满足。你通过自己的努力赢得了这一切，现在，是时候优雅地享受这份成果了。像花园中的女士一样，放慢脚步，欣赏你亲手创造的美。', meaningEn: 'This card represents Independence and fulfillment in the realm of material world and work. It brings the energy of money into your current situation, urging you to embrace this momentum with confidence. Trust in your ability to navigate this phase, as the 9 of Pentacles promises growth through engagement with health.', meaningReversed: '逆位的星币九指向表面的富足与内在的空虚、过度依赖物质享受与对独立的恐惧。你可能拥有许多外在的成功标志，但内心却感到一种难以言说的孤独与不安。或者，你害怕失去已经拥有的一切，以至于无法真正享受它。真正的丰盛不是银行账户的数字，而是一种无论发生什么都能照顾好自己的内在笃定。培养那种不依赖于外在条件的自信。', meaningReversedEn: 'The reversed 9 of Pentacles suggests blocked or delayed energy in material world and work. You may feel frustrated by obstacles or find that your enthusiasm for money is waning. This is a reminder to pause and reassess your approach rather than forcing progress. Look inward for what truly needs adjustment before moving forward again.', isReversed: false },
  { id: 73, name: '星币十', nameEn: 'Ten of Pentacles', suit: 'pentacles', meaning: '星币十中，三代同堂的家庭在拱门下欢聚，十枚星币镶嵌在拱门之上，象征着家族的传承、长期的财务安全与代际的丰盛。你可能正处于一个可以为自己和家人创造长久安稳的阶段。这不仅仅是关于金钱，更是关于建立一种可以传承下去的价值观、传统与遗产。你的努力不仅在滋养当下的自己，也在为未来的世代播种。这是一种最深沉的满足——知道你正在为更大的故事做出贡献。', meaningEn: 'This card represents Completion and culmination in the realm of material world and work. It brings the energy of money into your current situation, urging you to embrace this momentum with confidence. Trust in your ability to navigate this phase, as the 10 of Pentacles promises growth through engagement with health.', meaningReversed: '逆位的星币十揭示了家庭财务的危机、代际创伤的传递与对传统价值观的质疑。你可能正在经历家庭内部的金钱纠纷，或是发现自己被家族期待所束缚，无法追求真正属于自己的人生。或者，你质疑那些曾经被视为理所当然的传统与价值观。逆位的星币十提醒你：传承不应该成为牢笼，而应该成为翅膀。你有权利选择继承什么，也有权利选择放下什么。', meaningReversedEn: 'The reversed 10 of Pentacles suggests blocked or delayed energy in material world and work. You may feel frustrated by obstacles or find that your enthusiasm for money is waning. This is a reminder to pause and reassess your approach rather than forcing progress. Look inward for what truly needs adjustment before moving forward again.', isReversed: false },
  { id: 74, name: '星币侍从', nameEn: 'Page of Pentacles', suit: 'pentacles', meaning: '星币侍从站在田野中，双手捧着一枚星币，目光望向远方的新月，象征着新的学习机会、务实的梦想与对物质世界的好奇。你可能正处于一个充满学习热情的阶段，对新的技能、知识或投资机会充满兴趣。这张牌鼓励你：像侍从一样保持谦卑与好学的心态，脚踏实地地追求你的目标。你的梦想是可行的，但需要你一步一个脚印地去实现。新月代表着开始，而你的旅程，才刚刚启程。', meaningEn: 'This card represents New ideas and curiosity in the realm of material world and work. It brings the energy of money into your current situation, urging you to embrace this momentum with confidence. Trust in your ability to navigate this phase, as the page of Pentacles promises growth through engagement with health.', meaningReversed: '逆位的星币侍从暗示着缺乏实际行动的空想、对学习机会的浪费与财务上的不成熟。你可能有很多美好的想法，却迟迟不肯动手执行；或者你冲动地投入某个看似美好的机会，却没有做足够的研究。梦想需要行动来支撑，知识需要实践来验证。不要让「我还没准备好」成为你永远的借口——最好的准备，就是开始。', meaningReversedEn: 'The reversed page of Pentacles suggests blocked or delayed energy in material world and work. You may feel frustrated by obstacles or find that your enthusiasm for money is waning. This is a reminder to pause and reassess your approach rather than forcing progress. Look inward for what truly needs adjustment before moving forward again.', isReversed: false },
  { id: 75, name: '星币骑士', nameEn: 'Knight of Pentacles', suit: 'pentacles', meaning: '星币骑士骑着黑马，手持星币，稳健而专注地前行，象征着踏实、勤奋与对目标的持久坚持。你可能正处于一个需要耐心与毅力的阶段，没有捷径可走，只有一步一个脚印地前进。这张牌提醒你：慢不是弱点，反而是最可靠的速度。你的稳重与可靠是他人最信赖的品质。继续你的步伐，不要因为别人的匆忙而动摇——你的目的地在前方，而你已经走在了正确的道路上。', meaningEn: 'This card represents Action and pursuit in the realm of material world and work. It brings the energy of money into your current situation, urging you to embrace this momentum with confidence. Trust in your ability to navigate this phase, as the knight of Pentacles promises growth through engagement with health.', meaningReversed: '逆位的星币骑士揭示了固执的僵化、过度保守与缺乏变通的坚持。你可能像一匹拉磨的驴子，在原地打转却还以为自己在前进；或者你对变化的抗拒让你错过了更好的机会。踏实是美德，但如果变成了顽固与停滞不前，它就不再是优势。偶尔抬起头看看周围的世界，问问自己：你坚持的是目标本身，还是仅仅习惯了这种坚持的感觉？', meaningReversedEn: 'The reversed knight of Pentacles suggests blocked or delayed energy in material world and work. You may feel frustrated by obstacles or find that your enthusiasm for money is waning. This is a reminder to pause and reassess your approach rather than forcing progress. Look inward for what truly needs adjustment before moving forward again.', isReversed: false },
  { id: 76, name: '星币王后', nameEn: 'Queen of Pentacles', suit: 'pentacles', meaning: '星币王后坐在王座上，手中捧着星币，脚下是繁茂的花园与温顺的兔子，象征着滋养、务实的丰盛与将爱转化为具体关怀的能力。她是将抽象的情感落实为实际行动的大师——不是用言语说「我爱你」，而是为你做一顿热饭、帮你整理房间、在你需要时默默出现。你可能正处于一个需要将关怀化为实际行动的阶段，或是正在享受这种脚踏实地的温暖。滋养自己，也滋养你爱的人，因为生命的美好，就藏在这些具体的日常之中。', meaningEn: 'This card represents Nurturing and mastery in the realm of material world and work. It brings the energy of money into your current situation, urging you to embrace this momentum with confidence. Trust in your ability to navigate this phase, as the queen of Pentacles promises growth through engagement with health.', meaningReversed: '逆位的星币王后指向过度操劳、自我忽视与用物质替代情感关怀的倾向。你可能在不停地为他人付出，却忘了照顾自己的需求，直到身心俱疲；或者你认为用钱和礼物就可以解决一切关系问题，却忽视了真正的情感连接。你不需要成为完美的照顾者。允许自己也有被照顾的需要，允许自己偶尔什么都不做——因为你值得被温柔以待，包括被你自己。', meaningReversedEn: 'The reversed queen of Pentacles suggests blocked or delayed energy in material world and work. You may feel frustrated by obstacles or find that your enthusiasm for money is waning. This is a reminder to pause and reassess your approach rather than forcing progress. Look inward for what truly needs adjustment before moving forward again.', isReversed: false },
  { id: 77, name: '星币国王', nameEn: 'King of Pentacles', suit: 'pentacles', meaning: '星币国王端坐在他的王座上，身穿华丽的袍子，手握星币，身后是坚固的城堡与丰收的葡萄园。他是物质世界的统治者——不是贪婪的囤积者，而是懂得如何创造财富、管理资源并惠及他人的智者。你可能正处于一个可以充分发挥自己实际能力的阶段，或是在一个需要稳健领导力的位置上。像星币国王一样，用你成熟的判断力来规划、执行，并为身边的人创造安全与丰盛。', meaningEn: 'This card represents Authority and leadership in the realm of material world and work. It brings the energy of money into your current situation, urging you to embrace this momentum with confidence. Trust in your ability to navigate this phase, as the king of Pentacles promises growth through engagement with health.', meaningReversed: '逆位的星币国王揭示了物质主义的极端、贪婪与用财富来衡量一切价值的危险。你可能正在为了金钱而牺牲健康、关系与原则，或是用你的物质成功来操控和压制他人。或者，你对财务的恐惧让你变得吝啬与计算，失去了慷慨与信任的能力。真正的富足不是拥有最多，而是需要最少。重新审视你对财富的定义——它应该是通往自由的桥梁，而不是囚禁你的城堡。', meaningReversedEn: 'The reversed king of Pentacles suggests blocked or delayed energy in material world and work. You may feel frustrated by obstacles or find that your enthusiasm for money is waning. This is a reminder to pause and reassess your approach rather than forcing progress. Look inward for what truly needs adjustment before moving forward again.', isReversed: false },
];